// 销售状态开关（品牌粉，现代圆润）
function SaleSwitch({ on }: { on: boolean }) {
  const [s, setS] = useState(on);
  return (
    <button
      type="button"
      onClick={() => setS(!s)}
      className="inline-flex items-center gap-1.5 cursor-pointer"
      title={s ? "点击停售" : "点击在售"}
    >
      <span
        className="relative inline-block w-9 h-[18px] rounded-full transition-colors duration-200"
        style={{ background: s ? BRAND : "#d5d8e2", boxShadow: s ? `0 0 0 3px ${BRAND_SOFT}` : "none" }}
      >
        <span
          className="absolute top-[2px] h-[14px] w-[14px] rounded-full bg-white shadow transition-all duration-200"
          style={{ left: s ? "calc(100% - 16px)" : "2px" }}
        />
      </span>
      <span className="text-xs leading-none transition-colors" style={{ color: s ? BRAND : MUTED }}>
        {s ? "在售" : "停售"}
      </span>
    </button>
  );
}

// 驳回状态：叹号 icon + 悬浮提示（弹窗样式与风控产品保持一致）
function RejectTag({
  reason,
  fields,
  keywords,
  scanTime,
}: {
  reason: string;
  fields?: string;
  keywords?: string;
  scanTime?: string;
}) {
  const exMark = (
    <span
      className="inline-flex items-center justify-center w-[15px] h-[15px] rounded-full align-middle text-[11px] leading-none font-bold"
      style={{ background: BRAND, color: "#fff", boxShadow: "0 2px 5px rgba(233,30,99,.4)" }}
    >
      !
    </span>
  );
  return (
    <span className="relative inline-flex items-center cursor-pointer group align-middle">
      <span className="inline-flex items-center gap-1 text-[13px]" style={{ color: BRAND }}>
        <span>是（已驳回）</span>
        {exMark}
      </span>
      <span
        className="absolute left-0 top-full z-30 mt-1.5 w-[360px] max-w-[400px] whitespace-normal pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-150 rounded-lg p-3.5"
        style={{
          background: "#fff",
          border: `1px solid ${BRAND_SOFT}`,
          boxShadow: "0 8px 24px rgba(25,28,50,.12)",
        }}
      >
        <div className="flex items-center gap-1.5 mb-1.5 text-[13px] font-semibold" style={{ color: BRAND }}>
          {exMark}
          驳回原因
        </div>
        <p className="text-[12px] leading-relaxed mb-2" style={{ color: "#4a4e63" }}>{reason}</p>
        {(fields || keywords || scanTime) && (
          <div className="text-[12px] leading-relaxed" style={{ color: "#4a4e63" }}>
            {fields && (
              <div>
                <span className="text-[#1f2233] font-medium">命中字段：</span>
                {fields}
              </div>
            )}
            {keywords && (
              <div>
                <span className="text-[#1f2233] font-medium">命中关键词：</span>
                {keywords}
              </div>
            )}
            {scanTime && (
              <div>
                <span className="text-[#1f2233] font-medium">扫描时间：</span>
                {scanTime}
              </div>
            )}
          </div>
        )}
      </span>
    </span>
  );
}

