import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import Pagination from './Pagination';
import { Plus, Eye, ArrowUp, ArrowDown, Check, X, ExternalLink, Send, Calendar, ChevronDown, RotateCcw } from 'lucide-react';

interface NewsItem {
  id: number;
  title: string;
  category: string;
  summary: string;
  content: string;
  cover_image: string;
  status: string;
  enabled: number;
  is_draft: number;
  pv: number;
  uv: number;
  sort_order: number;
  source: string;
  publish_at: string | null;
  actual_publish_at: string | null;
  creator: string;
  create_date: string;
  modifier: string;
  modify_date: string;
}

const API_BASE = 'http://localhost:3001/api';
const CATEGORIES = ['公司新闻', '媒体关注', '党建动态', '多媒体中心', '信息公开'];
const SOURCES = ['众信旅游发言人', '悠护航'];

const NewsTable = () => {
  const [newsList, setNewsList] = useState<NewsItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [loading, setLoading] = useState(false);
  const [category, setCategory] = useState('');
  const [source, setSource] = useState('');
  const [keyword, setKeyword] = useState('');
  const [creator, setCreator] = useState('');
  const [modifier, setModifier] = useState('');
  const [status, setStatus] = useState<string>(''); // '' = 全部; 'published' | 'pending' | 'revoked'
  const [counts, setCounts] = useState<{ all: number; published: number; pending: number; revoked: number }>({
    all: 0, published: 0, pending: 0, revoked: 0,
  });
  const [editingSortId, setEditingSortId] = useState<number | null>(null);
  const [editingSortValue, setEditingSortValue] = useState<string>('');
  const [openPublishId, setOpenPublishId] = useState<number | null>(null);
  const [scheduleFor, setScheduleFor] = useState<{ id: number; defaultTime: string } | null>(null);
  const publishMenuRef = useRef<HTMLDivElement | null>(null);

  const fetchNews = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE}/news`, {
        params: { page, pageSize, category, source, keyword, creator, modifier, status }
      });
      if (res.data.code === 200) {
        setNewsList(res.data.data.list);
        setTotal(res.data.data.total);
      }
    } catch (error) {
      console.error('获取新闻列表失败:', error);
    }
    setLoading(false);
  };

  const fetchCounts = async () => {
    try {
      const res = await axios.get(`${API_BASE}/news/counts`, {
        params: { category, source, keyword, creator, modifier }
      });
      if (res.data.code === 200 && res.data.data) {
        setCounts(res.data.data);
      }
    } catch (error) {
      console.error('获取状态计数失败:', error);
    }
  };

  const refetch = () => {
    fetchNews();
    fetchCounts();
  };

  useEffect(() => {
    refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, pageSize, category, source, status]);

  const handleToggleEnabled = async (news: NewsItem) => {
    try {
      await axios.patch(`${API_BASE}/news/${news.id}/toggle`, {
        enabled: news.enabled === 1 ? 0 : 1,
        modifier: '当前用户',
      });
      fetchNews();
    } catch (error) {
      console.error('切换状态失败:', error);
    }
  };

  // 计算当前状态：已发布 / 待发布 / 已撤销
  // 待发布 = 草稿(is_draft=1) + 定时发布(有未来 publish_at)
  const getPublishState = (news: NewsItem): 'published' | 'pending' | 'revoked' => {
    if (news.is_draft === 1) return 'pending';
    if (news.enabled !== 1) return 'revoked';
    if (news.publish_at) return 'pending';
    return 'published';
  };

  // 立即发布
  const handlePublishNow = async (news: NewsItem) => {
    try {
      await axios.post(`${API_BASE}/news/${news.id}/publish`, { modifier: '当前用户' });
      setOpenPublishId(null);
      refetch();
    } catch (error) {
      console.error('发布失败:', error);
      alert('发布失败');
    }
  };

  // 打开定时发布弹窗
  const openSchedule = (news: NewsItem) => {
    setOpenPublishId(null);
    // 默认时间：当前时间 + 1 小时，格式 'YYYY-MM-DDTHH:MM'
    const d = new Date(Date.now() + 60 * 60 * 1000);
    const pad = (n: number) => String(n).padStart(2, '0');
    const defaultTime =
      `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
    setScheduleFor({ id: news.id, defaultTime });
  };

  // 确认定时发布
  const handleSchedulePublish = async () => {
    if (!scheduleFor) return;
    if (!scheduleFor.defaultTime) {
      alert('请选择发布时间');
      return;
    }
    try {
      await axios.post(`${API_BASE}/news/${scheduleFor.id}/publish`, {
        publish_at: scheduleFor.defaultTime,
        modifier: '当前用户',
      });
      setScheduleFor(null);
      refetch();
    } catch (error) {
      console.error('定时发布失败:', error);
      alert('定时发布失败');
    }
  };

  // 撤销
  const handleRevoke = async (news: NewsItem) => {
    if (!confirm(`确定撤销「${news.title}」吗？`)) return;
    try {
      await axios.post(`${API_BASE}/news/${news.id}/revoke`, { modifier: '当前用户' });
      refetch();
    } catch (error) {
      console.error('撤销失败:', error);
      alert('撤销失败');
    }
  };

  // 点击外部关闭发布下拉
  useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      if (publishMenuRef.current && !publishMenuRef.current.contains(e.target as Node)) {
        setOpenPublishId(null);
      }
    };
    if (openPublishId !== null) {
      document.addEventListener('mousedown', onDocClick);
      return () => document.removeEventListener('mousedown', onDocClick);
    }
  }, [openPublishId]);

  const handleDelete = async (id: number) => {
    if (!confirm('确定删除这条新闻吗？')) return;
    try {
      await axios.delete(`${API_BASE}/news/${id}`);
      refetch();
    } catch (error) {
      console.error('删除失败:', error);
    }
  };

  const handleSearch = () => {
    setPage(1);
    refetch();
  };

  const handleReset = () => {
    setCategory('');
    setSource('');
    setKeyword('');
    setCreator('');
    setModifier('');
    setStatus('');
    setPage(1);
  };

  // 保存排序
  const handleSortSave = async (news: NewsItem) => {
    const newVal = Number(editingSortValue);
    if (isNaN(newVal) || newVal < 0) {
      alert('排序值必须为非负整数');
      return;
    }
    if (newVal === news.sort_order) {
      setEditingSortId(null);
      return;
    }
    try {
      await axios.patch(`${API_BASE}/news/${news.id}/sort`, {
        sort_order: newVal,
        modifier: '当前用户',
      });
      setEditingSortId(null);
      refetch();
    } catch (error) {
      console.error('更新排序失败:', error);
      alert('更新排序失败');
    }
  };

  // 上移/下移：与相邻行交换 sort_order
  const handleSortSwap = async (news: NewsItem, direction: 'up' | 'down') => {
    const sorted = [...newsList].sort((a, b) => {
      if (a.sort_order !== b.sort_order) return a.sort_order - b.sort_order;
      return b.id - a.id;
    });
    const idx = sorted.findIndex(n => n.id === news.id);
    const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
    if (targetIdx < 0 || targetIdx >= sorted.length) return;
    const target = sorted[targetIdx];
    try {
      // 交换两个 sort_order，后端会自动改 modify_date
      await Promise.all([
        axios.patch(`${API_BASE}/news/${news.id}/sort`, { sort_order: target.sort_order, modifier: '当前用户' }),
        axios.patch(`${API_BASE}/news/${target.id}/sort`, { sort_order: news.sort_order, modifier: '当前用户' }),
      ]);
      refetch();
    } catch (error) {
      console.error('调序失败:', error);
      alert('调序失败');
    }
  };

  return (
    <div className="bg-white">
      {/* 标题栏 */}
      <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
        <h3 className="text-sm font-bold text-gray-800">众信动态配置</h3>
        <Link
          to="/admin/news/edit"
          className="flex items-center gap-1 px-3 py-1.5 bg-red-500 text-white text-sm rounded hover:bg-red-600 transition-colors"
        >
          <Plus className="w-4 h-4" />
          新增新闻
        </Link>
      </div>

      {/* 状态 Tabs */}
      <div className="border-b border-gray-200 px-4 flex items-center gap-6 bg-white">
        {[
          { key: '', label: '全部' },
          { key: 'published', label: '已发布' },
          { key: 'pending', label: '待发布' },
          { key: 'revoked', label: '已撤销' },
        ].map(tab => {
          const countKey = (tab.key || 'all') as keyof typeof counts;
          const count = counts[countKey] ?? 0;
          const active = status === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => { setStatus(tab.key); setPage(1); }}
              className={
                'py-3 text-sm border-b-2 transition-colors flex items-center gap-1.5 ' +
                (active
                  ? 'border-red-500 text-red-500 font-medium'
                  : 'border-transparent text-gray-600 hover:text-gray-800')
              }
            >
              {tab.label}
              <span className={active ? 'text-xs text-red-400' : 'text-xs text-gray-400'}>({count})</span>
            </button>
          );
        })}
      </div>

      {/* 筛选区 */}
      <div className="border-b border-gray-200 px-4 py-3 flex items-center gap-3 bg-gray-50">
        <select
          value={category}
          onChange={(e) => { setCategory(e.target.value); setPage(1); }}
          className="h-8 px-2 border border-gray-300 rounded text-xs bg-white focus:outline-none focus:border-red-400"
        >
          <option value="">全部分类</option>
          {CATEGORIES.map(c => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
        <select
          value={source}
          onChange={(e) => { setSource(e.target.value); setPage(1); }}
          className="h-8 px-2 border border-gray-300 rounded text-xs bg-white focus:outline-none focus:border-red-400"
        >
          <option value="">全部来源</option>
          {SOURCES.map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
        <input
          type="text"
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="标题/摘要/内容"
          className="h-8 w-40 px-3 border border-gray-300 rounded text-xs focus:outline-none focus:border-red-400"
        />
        <input
          type="text"
          value={creator}
          onChange={(e) => setCreator(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="创建人"
          className="h-8 w-28 px-3 border border-gray-300 rounded text-xs focus:outline-none focus:border-red-400"
        />
        <input
          type="text"
          value={modifier}
          onChange={(e) => setModifier(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="操作人"
          className="h-8 w-28 px-3 border border-gray-300 rounded text-xs focus:outline-none focus:border-red-400"
        />
        <button
          onClick={handleSearch}
          className="h-8 px-3 bg-red-500 text-white text-xs rounded hover:bg-red-600"
        >
          搜索
        </button>
        <button
          onClick={handleReset}
          className="h-8 px-3 border border-gray-300 text-gray-600 text-xs rounded hover:bg-gray-100"
        >
          重置
        </button>
      </div>

      {/* 表格 */}
      <div className="overflow-x-auto">
        <table className="w-full border-collapse">
          <thead>
            <tr style={{ backgroundColor: '#f3f5fc' }}>
              <th className="px-3 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5', width: 130 }}>排序</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>标题</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>封面</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>分类</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>来源</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>PV</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>创建人</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>创建日期</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>操作人</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>最近操作时间</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600" style={{ borderRight: '1px solid #e8ebf5' }}>状态</th>
              <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-600">操作</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={12} className="px-4 py-8 text-center text-gray-500 text-xs">加载中...</td>
              </tr>
            ) : newsList.length === 0 ? (
              <tr>
                <td colSpan={12} className="px-4 py-8 text-center text-gray-500 text-xs">暂无数据</td>
              </tr>
            ) : (
              newsList.map((news, index) => (
                <tr key={news.id} className={index % 2 === 1 ? 'bg-[#fafbfd]' : 'bg-white'}>
                  <td className="px-3 py-3 text-xs" style={{ borderRight: '1px solid #f0f0f0' }}>
                    {editingSortId === news.id ? (
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          min={0}
                          value={editingSortValue}
                          onChange={(e) => setEditingSortValue(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleSortSave(news);
                            if (e.key === 'Escape') setEditingSortId(null);
                          }}
                          autoFocus
                          className="w-12 h-6 px-1 border border-red-400 rounded text-xs text-center"
                        />
                        <button onClick={() => handleSortSave(news)} className="text-green-600 hover:text-green-800" title="保存">
                          <Check className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => setEditingSortId(null)} className="text-gray-400 hover:text-gray-600" title="取消">
                          <X className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-0.5">
                        <span
                          onClick={() => {
                            setEditingSortId(news.id);
                            setEditingSortValue(String(news.sort_order ?? 0));
                          }}
                          className="inline-block min-w-[28px] px-1.5 h-6 leading-6 text-center bg-gray-50 border border-gray-200 rounded text-gray-700 font-mono cursor-pointer hover:border-red-300 hover:bg-red-50"
                          title="点击修改"
                        >
                          {news.sort_order ?? 0}
                        </span>
                        <button
                          onClick={() => handleSortSwap(news, 'up')}
                          disabled={index === 0}
                          className={'p-0.5 rounded ' + (index === 0 ? 'text-gray-300 cursor-not-allowed' : 'text-gray-500 hover:text-red-500 hover:bg-red-50')}
                          title="上移"
                        >
                          <ArrowUp className="w-3 h-3" />
                        </button>
                        <button
                          onClick={() => handleSortSwap(news, 'down')}
                          disabled={index === newsList.length - 1}
                          className={'p-0.5 rounded ' + (index === newsList.length - 1 ? 'text-gray-300 cursor-not-allowed' : 'text-gray-500 hover:text-red-500 hover:bg-red-50')}
                          title="下移"
                        >
                          <ArrowDown className="w-3 h-3" />
                        </button>
                      </div>
                    )}
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-700 max-w-xs truncate" style={{ borderRight: '1px solid #f0f0f0' }}>
                    {news.title}
                  </td>
                  <td className="px-4 py-3" style={{ borderRight: '1px solid #f0f0f0' }}>
                    {news.cover_image ? (
                      <img
                        src={news.cover_image}
                        alt={news.title}
                        className="w-16 h-10 object-cover rounded border border-gray-200"
                      />
                    ) : (
                      <div className="w-16 h-10 bg-gray-100 rounded border border-gray-200 flex items-center justify-center text-gray-400 text-[10px]">
                        无封面
                      </div>
                    )}
                  </td>
                  <td className="px-4 py-3 text-xs" style={{ borderRight: '1px solid #f0f0f0' }}>
                    <span className="px-2 py-0.5 bg-red-50 text-red-600 rounded text-xs">
                      {news.category || '公司新闻'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600" style={{ borderRight: '1px solid #f0f0f0' }}>
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-blue-50 text-blue-600 rounded text-xs">
                      {news.source || '众信旅游发言人'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-700 font-mono" style={{ borderRight: '1px solid #f0f0f0' }}>
                    <span className="inline-flex items-center gap-1 text-red-500">
                      <Eye className="w-3 h-3" />
                      {(news.pv || 0).toLocaleString()}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600" style={{ borderRight: '1px solid #f0f0f0' }}>{news.creator}</td>
                  <td className="px-4 py-3 text-xs text-gray-600" style={{ borderRight: '1px solid #f0f0f0' }}>{news.create_date}</td>
                  <td className="px-4 py-3 text-xs text-gray-600" style={{ borderRight: '1px solid #f0f0f0' }}>{news.modifier || '-'}</td>
                  <td className="px-4 py-3 text-xs text-gray-600" style={{ borderRight: '1px solid #f0f0f0' }}>{news.modify_date || '-'}</td>
                  <td className="px-4 py-3 text-xs" style={{ borderRight: '1px solid #f0f0f0' }}>
                    {(() => {
                      const state = getPublishState(news);
                      if (state === 'published') {
                        return (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-green-50 text-green-600 rounded text-xs">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
                            已发布
                          </span>
                        );
                      }
                      if (state === 'pending') {
                        // 草稿态(is_draft=1) 无发布时间；定时态有
                        const isDraft = news.is_draft === 1;
                        return (
                          <div className="flex flex-col gap-0.5">
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-amber-50 text-amber-600 rounded text-xs w-fit">
                              <span className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                              待发布
                            </span>
                            <span className="text-[10px] text-gray-400">
                              {isDraft
                                ? '草稿'
                                : news.publish_at?.replace('T', ' ').substring(0, 16)}
                            </span>
                          </div>
                        );
                      }
                      return (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-gray-100 text-gray-500 rounded text-xs">
                          <span className="w-1.5 h-1.5 rounded-full bg-gray-400" />
                          已撤销
                        </span>
                      );
                    })()}
                  </td>
                  <td className="px-4 py-3 text-xs">
                    <div className="flex gap-2 items-center">
                      {/* 发布按钮 - 已撤销 或 待发布 时显示（待发布用于改期 / 立即触发）*/}
                      {getPublishState(news) !== 'published' && (
                        <div className="relative">
                          <button
                            onClick={() => setOpenPublishId(openPublishId === news.id ? null : news.id)}
                            className={'inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs border transition-colors ' +
                              (getPublishState(news) === 'revoked'
                                ? 'border-red-300 text-red-500 hover:bg-red-50'
                                : 'border-amber-300 text-amber-600 hover:bg-amber-50')}
                            title="发布"
                          >
                            <Send className="w-3 h-3" />
                            发布
                            <ChevronDown className="w-3 h-3" />
                          </button>
                          {openPublishId === news.id && (
                            <div
                              ref={publishMenuRef}
                              className="absolute z-20 mt-1 left-0 w-36 bg-white border border-gray-200 rounded shadow-lg py-1"
                            >
                              <button
                                onClick={() => handlePublishNow(news)}
                                className="w-full text-left px-3 py-1.5 text-xs text-gray-700 hover:bg-gray-50 flex items-center gap-1.5"
                              >
                                <Send className="w-3 h-3 text-red-500" />
                                立即发布
                              </button>
                              <button
                                onClick={() => openSchedule(news)}
                                className="w-full text-left px-3 py-1.5 text-xs text-gray-700 hover:bg-gray-50 flex items-center gap-1.5"
                              >
                                <Calendar className="w-3 h-3 text-amber-500" />
                                定时发布…
                              </button>
                            </div>
                          )}
                        </div>
                      )}

                      {/* 撤销按钮 - 仅已发布 时显示（已发布内容只能下架，不能删除）*/}
                      {getPublishState(news) === 'published' && (
                        <button
                          onClick={() => handleRevoke(news)}
                          className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs border border-gray-300 text-gray-500 hover:bg-gray-50"
                          title="撤销发布"
                        >
                          <RotateCcw className="w-3 h-3" />
                          撤销
                        </button>
                      )}

                      <Link
                        to={`/admin/news/preview/${news.id}`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-500 hover:text-blue-700 font-medium inline-flex items-center gap-0.5"
                        title="前端预览"
                      >
                        <ExternalLink className="w-3 h-3" />
                        预览
                      </Link>
                      <Link
                        to={`/admin/news/edit/${news.id}`}
                        className="text-[#ed1e4e] hover:text-[#c41840] font-medium"
                      >
                        编辑
                      </Link>
                      {/* 删除按钮 - 已发布 不可删除（必须先撤销）；待发布/已撤销可删除 */}
                      {getPublishState(news) !== 'published' && (
                        <button
                          onClick={() => handleDelete(news.id)}
                          className="text-gray-500 hover:text-gray-700 font-medium"
                        >
                          删除
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Pagination total={total} page={page} pageSize={pageSize} />

      {/* 定时发布弹窗 */}
      {scheduleFor && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl w-[420px] p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-bold text-gray-800 flex items-center gap-2">
                <Calendar className="w-4 h-4 text-amber-500" />
                定时发布
              </h3>
              <button
                onClick={() => setScheduleFor(null)}
                className="text-gray-400 hover:text-gray-600"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="mb-4">
              <label className="block text-xs text-gray-500 mb-1.5">发布时间</label>
              <input
                type="datetime-local"
                value={scheduleFor.defaultTime}
                onChange={(e) => setScheduleFor({ ...scheduleFor, defaultTime: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
              />
              <p className="text-xs text-gray-400 mt-1.5">
                系统会在到达该时间后自动发布；过去时间会立即发布。
              </p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={handleSchedulePublish}
                className="flex-1 flex items-center justify-center gap-1 px-4 py-2 bg-red-500 text-white text-sm rounded hover:bg-red-600"
              >
                <Calendar className="w-4 h-4" />
                确认发布
              </button>
              <button
                onClick={() => setScheduleFor(null)}
                className="flex-1 px-4 py-2 border border-gray-300 text-sm rounded hover:bg-gray-50"
              >
                取消
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default NewsTable;