import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import {
  ArrowLeft, Save, Bold, Italic, Underline,
  AlignLeft, AlignCenter, AlignRight, List, ListOrdered, Quote,
  Link2, Image, Code, Undo, Redo, Upload, X, Eye
} from 'lucide-react';

interface NewsItem {
  id: number;
  title: string;
  category: string;
  summary: string;
  content: string;
  cover_image: string;
  status: string;
  enabled: number;
  source: string;
  actual_publish_at: string | null;
}

const API_BASE = 'http://localhost:3001/api';
const CATEGORIES = ['公司新闻', '媒体关注', '党建动态', '多媒体中心', '信息公开'];
const SOURCES = ['众信旅游发言人', '悠护航'];

const AdminNewsEdit = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = !!id;

  const [form, setForm] = useState({
    title: '',
    category: '公司新闻',
    summary: '',
    content: '',
    cover_image: '',
    source: '众信旅游发言人',
    actual_publish_at: '',
  });
  const [author, setAuthor] = useState('当前用户');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showLinkDialog, setShowLinkDialog] = useState(false);
  const [linkUrl, setLinkUrl] = useState('');
  const editorRef = useRef<HTMLDivElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const editorImageInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEdit) {
      fetchNews();
    }
  }, [id]);

  const fetchNews = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE}/news/${id}`);
      if (res.data.code === 200) {
        const n = res.data.data;
        setForm({
          title: n.title || '',
          category: n.category || '公司新闻',
          summary: n.summary || '',
          content: n.content || '',
          cover_image: n.cover_image || '',
          source: n.source || '众信旅游发言人',
          actual_publish_at: n.actual_publish_at ? n.actual_publish_at.replace(' ', 'T').substring(0, 16) : '',
        });
        if (editorRef.current) {
          editorRef.current.innerHTML = n.content || '';
        }
      }
    } catch (error) {
      console.error('获取新闻失败:', error);
    }
    setLoading(false);
  };

  const exec = (command: string, value?: string) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertLink = () => {
    if (!linkUrl) return;
    editorRef.current?.focus();
    if (linkUrl) {
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0) {
        const range = sel.getRangeAt(0);
        const a = document.createElement('a');
        a.href = linkUrl;
        a.textContent = sel.toString() || linkUrl;
        a.target = '_blank';
        a.className = 'text-blue-500 underline';
        range.deleteContents();
        range.insertNode(a);
      }
    }
    setShowLinkDialog(false);
    setLinkUrl('');
    syncContent();
  };

  const syncContent = () => {
    if (editorRef.current) {
      setForm(f => ({ ...f, content: editorRef.current!.innerHTML }));
    }
  };

  // 工具栏：插入base64图片
  const handleEditorImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const dataUrl = ev.target?.result as string;
      editorRef.current?.focus();
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0) {
        const range = sel.getRangeAt(0);
        const img = document.createElement('img');
        img.src = dataUrl;
        img.className = 'max-w-full my-2 rounded';
        img.alt = file.name;
        range.insertNode(img);
      } else {
        editorRef.current!.innerHTML += `<img src="${dataUrl}" class="max-w-full my-2 rounded" />`;
      }
      syncContent();
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  // 工具栏：插入视频
  const insertVideo = () => {
    const url = prompt('请输入视频URL (mp4格式):');
    if (url && editorRef.current) {
      editorRef.current.focus();
      const video = document.createElement('video');
      video.src = url;
      video.controls = true;
      video.className = 'max-w-full my-2 rounded';
      editorRef.current.appendChild(video);
      syncContent();
    }
  };

  // 封面图上传
  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      setForm(f => ({ ...f, cover_image: ev.target?.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!form.title.trim()) {
      alert('请输入标题');
      return;
    }
    if (!form.summary.trim()) {
      alert('请输入摘要');
      return;
    }
    if (!form.cover_image) {
      alert('请上传封面图片');
      return;
    }
    if (!form.content.trim() || form.content === '<br>') {
      alert('请输入内容');
      return;
    }
    syncContent();
    setSaving(true);
    // datetime-local 'YYYY-MM-DDTHH:MM' -> 'YYYY-MM-DD HH:MM:SS'
    const actualPublishAt = form.actual_publish_at
      ? form.actual_publish_at.replace('T', ' ') + ':00'
      : '';
    const submitForm = { ...form, actual_publish_at: actualPublishAt };
    try {
      if (isEdit) {
        await axios.put(`${API_BASE}/news/${id}`, {
          ...submitForm,
          modifier: author,
        });
      } else {
        await axios.post(`${API_BASE}/news`, {
          ...submitForm,
          creator: author,
        });
      }
      navigate('/admin/news');
    } catch (error) {
      console.error('保存失败:', error);
      alert('保存失败，请重试');
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="flex min-h-screen bg-gray-100">
        <div className="flex-1 flex items-center justify-center text-gray-500 text-sm">加载中...</div>
      </div>
    );
  }

  const tbBtn = 'p-1.5 hover:bg-gray-100 rounded text-gray-600 transition-colors';
  const tbSep = 'w-px h-5 bg-gray-200 mx-1';

  return (
    <div className="flex min-h-screen bg-gray-100">
      <div className="flex-1 flex flex-col">
        {/* 顶部 */}
        <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Link to="/admin/news" className="text-gray-500 hover:text-gray-700">
              <ArrowLeft className="w-4 h-4" />
            </Link>
            <span className="text-sm font-bold text-gray-800">
              {isEdit ? '编辑新闻' : '新增新闻'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {isEdit && id && (
              <Link
                to={`/admin/news/preview/${id}`}
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-1 px-3 py-1.5 border border-blue-400 text-blue-500 text-sm rounded hover:bg-blue-50"
                title="在新窗口打开前端预览"
              >
                <Eye className="w-4 h-4" />
                预览
              </Link>
            )}
            <button
              onClick={() => navigate('/admin/news')}
              className="px-3 py-1.5 border border-gray-300 text-gray-700 text-sm rounded hover:bg-gray-50"
            >
              取消
            </button>
            <button
              onClick={handleSave}
              disabled={saving}
              className="flex items-center gap-1 px-4 py-1.5 bg-red-500 text-white text-sm rounded hover:bg-red-600"
            >
              <Save className="w-4 h-4" />
              {saving ? '保存中...' : '保存'}
            </button>
          </div>
        </div>

        {/* 表单 */}
        <div className="flex-1 p-6 overflow-auto">
          <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-sm p-6 space-y-5">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                标题 <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                placeholder="请输入新闻标题"
                className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  分类 <span className="text-red-500">*</span>
                </label>
                <select
                  value={form.category}
                  onChange={(e) => setForm({ ...form, category: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
                >
                  {CATEGORIES.map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  作者 <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={author}
                  onChange={(e) => setAuthor(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  来源 <span className="text-red-500">*</span>
                </label>
                <select
                  value={form.source}
                  onChange={(e) => setForm({ ...form, source: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
                >
                  {SOURCES.map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">
                  实际发稿时间
                </label>
                <input
                  type="datetime-local"
                  value={form.actual_publish_at}
                  onChange={(e) => setForm({ ...form, actual_publish_at: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                摘要 <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={form.summary}
                onChange={(e) => setForm({ ...form, summary: e.target.value })}
                placeholder="选填，不填则自动截取正文前54字"
                className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-red-400"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                封面图片 <span className="text-red-500">*</span>
              </label>
              {form.cover_image ? (
                <div className="relative w-48 h-28 border border-gray-200 rounded overflow-hidden">
                  <img src={form.cover_image} alt="封面" className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={() => setForm({ ...form, cover_image: '' })}
                    className="absolute top-1 right-1 w-5 h-5 bg-black/50 text-white rounded-full flex items-center justify-center hover:bg-black/70"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ) : (
                <div
                  onClick={() => coverInputRef.current?.click()}
                  className="w-48 h-28 border-2 border-dashed border-gray-300 rounded cursor-pointer hover:border-red-400 transition-colors flex flex-col items-center justify-center text-gray-400"
                >
                  <Upload className="w-6 h-6 mb-1" />
                  <span className="text-xs">点击上传封面</span>
                </div>
              )}
              <input
                ref={coverInputRef}
                type="file"
                accept="image/*"
                onChange={handleCoverUpload}
                className="hidden"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                内容 <span className="text-red-500">*</span>
              </label>
              {/* 工具栏 */}
              <div className="border border-gray-300 border-b-0 rounded-t bg-gray-50 px-2 py-1 flex items-center flex-wrap gap-0.5">
                <button type="button" onClick={() => exec('undo')} className={tbBtn} title="撤销">
                  <Undo className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('redo')} className={tbBtn} title="重做">
                  <Redo className="w-3.5 h-3.5" />
                </button>
                <div className={tbSep} />
                <button type="button" onClick={() => exec('bold')} className={tbBtn} title="加粗">
                  <Bold className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('italic')} className={tbBtn} title="斜体">
                  <Italic className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('underline')} className={tbBtn} title="下划线">
                  <Underline className="w-3.5 h-3.5" />
                </button>
                <div className={tbSep} />
                <button type="button" onClick={() => exec('justifyLeft')} className={tbBtn} title="左对齐">
                  <AlignLeft className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('justifyCenter')} className={tbBtn} title="居中">
                  <AlignCenter className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('justifyRight')} className={tbBtn} title="右对齐">
                  <AlignRight className="w-3.5 h-3.5" />
                </button>
                <div className={tbSep} />
                <button type="button" onClick={() => exec('insertUnorderedList')} className={tbBtn} title="无序列表">
                  <List className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('insertOrderedList')} className={tbBtn} title="有序列表">
                  <ListOrdered className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('formatBlock', 'blockquote')} className={tbBtn} title="引用">
                  <Quote className="w-3.5 h-3.5" />
                </button>
                <div className={tbSep} />
                <button type="button" onClick={() => setShowLinkDialog(true)} className={tbBtn} title="插入链接">
                  <Link2 className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => editorImageInputRef.current?.click()} className={tbBtn} title="插入图片">
                  <Image className="w-3.5 h-3.5" />
                </button>
                <input
                  ref={editorImageInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleEditorImage}
                  className="hidden"
                />
                <button type="button" onClick={insertVideo} className={tbBtn} title="插入视频">
                  <Image className="w-3.5 h-3.5" />
                </button>
                <button type="button" onClick={() => exec('formatBlock', 'pre')} className={tbBtn} title="代码块">
                  <Code className="w-3.5 h-3.5" />
                </button>
              </div>
              <div
                ref={editorRef}
                contentEditable
                onInput={syncContent}
                onBlur={syncContent}
                className="w-full min-h-[260px] px-3 py-2 border border-gray-300 rounded-b text-sm focus:outline-none focus:border-red-400 leading-relaxed [&_img]:max-w-full [&_img]:my-2 [&_blockquote]:border-l-4 [&_blockquote]:border-gray-300 [&_blockquote]:pl-3 [&_blockquote]:text-gray-500 [&_pre]:bg-gray-100 [&_pre]:p-2 [&_pre]:rounded [&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5"
                style={{ wordBreak: 'break-word' }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* 链接弹窗 */}
      {showLinkDialog && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl w-96 p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-bold text-gray-800">插入链接</h3>
              <button onClick={() => setShowLinkDialog(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div>
              <label className="block text-xs text-gray-500 mb-1">链接地址</label>
              <input
                type="text"
                value={linkUrl}
                onChange={(e) => setLinkUrl(e.target.value)}
                placeholder="https://..."
                className="w-full px-3 py-2 border border-gray-300 rounded text-sm"
                autoFocus
              />
            </div>
            <div className="flex gap-2 mt-4">
              <button
                onClick={insertLink}
                className="flex-1 px-4 py-2 bg-red-500 text-white text-sm rounded hover:bg-red-600"
              >
                确定
              </button>
              <button
                onClick={() => setShowLinkDialog(false)}
                className="flex-1 px-4 py-2 border border-gray-300 text-sm rounded hover:bg-gray-50"
              >
                取消
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminNewsEdit;