// 在分栏式菜单中查找叶子节点 path（取路径最长/最精确的匹配，避免 /admin 吞掉 /admin/xxx）
const findPathInMenu = (items: MenuItem[], path: string): { item: MenuItem; leafPath: string } | null => {
  let best: { item: MenuItem; leafPath: string } | null = null;
  let bestLen = -1;
  for (const item of items) {
    if (item.submenuGroups) {
      for (const grp of item.submenuGroups) {
        for (const leaf of grp.items) {
          if (leaf.path === '#' || leaf.path === '') continue;
          const exact = path === leaf.path;
          const under = leaf.path !== '/admin' && path.startsWith(leaf.path);
          const adminRoot = leaf.path === '/admin' && path.startsWith('/admin');
          if (exact || under || adminRoot) {
            if (leaf.path.length > bestLen) {
              best = { item, leafPath: leaf.path };
              bestLen = leaf.path.length;
            }
          }
        }
      }
    }
    if (item.path && path.startsWith(item.path)) {
      if (item.path.length > bestLen) {
        best = { item, leafPath: '' };
        bestLen = item.path.length;
      }
    }
  }
  return best;
};

const Sidebar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [activeItem, setActiveItem] = useState<number>(3);
  const [openSubmenuId, setOpenSubmenuId] = useState<number | null>(null);
  const [activeLeafPath, setActiveLeafPath] = useState<string>('');
  const sidebarRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const found = findPathInMenu(menuItems, location.pathname);
    if (found) {
      setActiveItem(found.item.id);
      setActiveLeafPath(found.leafPath);
    }
  }, [location.pathname]);

  useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      if (sidebarRef.current && !sidebarRef.current.contains(e.target as Node)) {
        setOpenSubmenuId(null);
      }
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, []);

  const handleClick = (item: MenuItem) => {
    setActiveItem(item.id);
    if (item.hasSubmenu && item.submenuGroups) {
      setOpenSubmenuId(openSubmenuId === item.id ? null : item.id);
    } else {
      setOpenSubmenuId(null);
      if (item.path) navigate(item.path);
    }
  };

  const handleLeafClick = (parentId: number, leaf: LeafMenuItem) => {
    if (leaf.path === '#') return;
    if (leaf.path.startsWith('http://') || leaf.path.startsWith('https://')) {
      setOpenSubmenuId(null);
      window.open(leaf.path, '_blank', 'noopener');
      return;
    }
    setActiveItem(parentId);
    setActiveLeafPath(leaf.path);
    setOpenSubmenuId(null);
    navigate(leaf.path);
  };

  return (
    <div
      ref={sidebarRef}
      className="w-[208px] min-h-screen flex flex-col flex-shrink-0 relative"
      style={{ background: '#1c1e30' }}
    >
      <nav className="flex-1 py-1">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeItem === item.id;
          const isOpen = openSubmenuId === item.id;
          return (
            <div key={item.id} className="relative">
              <button
                onClick={() => handleClick(item)}
                onMouseEnter={() => {
                  if (item.hasSubmenu && item.submenuGroups) {
                    setOpenSubmenuId(item.id);
                  }
                }}
                className={`w-full flex items-center px-4 py-[10px] text-[13px] transition-colors ${
                  isActive && !isOpen
                    ? 'text-white'
                    : 'text-gray-300 hover:bg-[#2a2d45] hover:text-white'
                }`}
                style={isActive && !isOpen ? { background: '#2f3351', boxShadow: 'inset 3px 0 0 #E91E63', color: '#fff' } : {}}
              >
                <Icon className="w-4 h-4 mr-3 flex-shrink-0" strokeWidth={isActive && !isOpen ? 2.5 : 2} />
                <span className="flex-1 text-left">{item.name}</span>
                {item.hasSubmenu && (
                  <ChevronRight
                    className={`w-3.5 h-3.5 transition-transform ${
                      isOpen ? 'rotate-90 text-white' : isActive ? 'text-white' : 'text-gray-500'
                    }`}
                  />
                )}
              </button>

              {/* 分栏式二级菜单（横排多栏，每栏=红色竖线标题+菜单项列表） */}
              {item.hasSubmenu && item.submenuGroups && item.submenuGroups.length > 0 && isOpen && (
                <div
                  className="absolute left-full top-0 ml-2 z-50 rounded-lg overflow-hidden shadow-2xl"
                  style={{ background: '#1c1e30', border: '1px solid #3a3a3a' }}
                  onMouseLeave={() => setOpenSubmenuId(null)}
                >
                  <div className="flex">
                    {item.submenuGroups.map((grp, grpIdx) => (
                      <div
                        key={grp.title}
                        className="px-5 py-4 min-w-[170px]"
                        style={grpIdx < item.submenuGroups!.length - 1 ? { borderRight: '1px solid #3a3a3a' } : {}}
                      >
                        {/* 分栏标题（左侧红色竖线） */}
                        <div className="flex items-center mb-3">
                          <span
                            className="w-[3px] h-4 mr-2 rounded-sm"
                            style={{ background: '#E91E63' }}
                          />
                          <span className="text-white text-[13px] font-semibold">
                            {grp.title}
                          </span>
                        </div>
                        {/* 菜单项列表 */}
                        <ul className="space-y-1">
                          {grp.items.map(leaf => {
                            const isLeafActive = leaf.path !== '#' && activeLeafPath === leaf.path;
                            return (
                              <li key={leaf.name}>
                                <button
                                  onClick={() => handleLeafClick(item.id, leaf)}
                                  className={`w-full text-left px-1 py-2 text-[13px] rounded transition-colors ${
                                    isLeafActive
                                      ? 'text-white bg-[#E91E63]/20'
                                      : 'text-gray-300 hover:text-white hover:bg-[#2a2d45]'
                                  }`}
                                >
                                  {leaf.name}
                                </button>
                              </li>
                            );
                          })}
                        </ul>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </nav>
    </div>
  );
};

export default Sidebar;
