import { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { Newspaper, ChevronRight } from 'lucide-react';

interface NewsItem {
  id: number;
  title: string;
  summary: string;
}

const API_BASE = 'http://localhost:3001/api';

const NewsTicker = () => {
  const [newsList, setNewsList] = useState<NewsItem[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const animationRef = useRef<number>(0);
  const pausedRef = useRef(false);

  useEffect(() => {
    fetchNews();
  }, []);

  const fetchNews = async () => {
    try {
      const res = await axios.get(`${API_BASE}/news`, {
        params: { page: 1, pageSize: 20, enabled: 1 }
      });
      if (res.data.code === 200) {
        setNewsList(res.data.data.list);
      }
    } catch (error) {
      console.error('获取新闻失败:', error);
    }
  };

  useEffect(() => {
    if (newsList.length === 0) return;
    const track = trackRef.current;
    if (!track) return;

    let position = 0;
    const speed = 0.5;

    const animate = () => {
      if (!pausedRef.current && track) {
        position -= speed;
        if (Math.abs(position) >= track.scrollWidth / 2) {
          position = 0;
        }
        track.style.transform = `translateX(${position}px)`;
      }
      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationRef.current);
  }, [newsList]);

  if (newsList.length === 0) return null;

  // 复制一份数据实现无缝循环
  const displayList = [...newsList, ...newsList];

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
      <div className="flex items-stretch">
        {/* 左侧标签 */}
        <div className="flex items-center gap-1.5 px-4 text-red-600 flex-shrink-0 border-r border-gray-100">
          <Newspaper className="w-4 h-4" />
          <span className="text-sm font-bold">众信动态</span>
        </div>

        {/* 跑马灯容器 */}
        <div
          ref={containerRef}
          className="flex-1 overflow-hidden h-10"
          onMouseEnter={() => { pausedRef.current = true; }}
          onMouseLeave={() => { pausedRef.current = false; }}
        >
          <div
            ref={trackRef}
            className="flex items-center gap-10 whitespace-nowrap h-full"
            style={{ willChange: 'transform' }}
          >
            {displayList.map((news, idx) => (
              <Link
                key={`${news.id}-${idx}`}
                to="/news"
                className="text-sm text-gray-600 hover:text-red-500 transition-colors flex items-center gap-2 flex-shrink-0"
              >
                <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                {news.title}
              </Link>
            ))}
          </div>
        </div>

        {/* 右侧查看全部 */}
        <Link
          to="/news"
          className="flex items-center gap-1 px-4 text-sm text-gray-500 hover:text-red-500 flex-shrink-0 border-l border-gray-100 transition-colors"
        >
          查看全部
          <ChevronRight className="w-3.5 h-3.5" />
        </Link>
      </div>
    </div>
  );
};

export default NewsTicker;