import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Sidebar from '../components/Admin/Sidebar';
import TopBar from '../components/Admin/TopBar';
import { isEmbed } from '../lib/embed';
import Pagination from '../components/Admin/Pagination';
import { Plus, Search, RotateCcw, Eye, Edit3, Copy, Link2, Trash2, Check } from 'lucide-react';

interface Activity {
  id: number;
  name: string;
  type: string;
  scope: string;
  link: string;
  status: 'published' | 'unpublished' | 'offline';
  views: number;
  viewers: number;
  shares: number;
  startTime: string;
  endTime: string;
  creator: string;
  createTime: string;
  modifier: string;
  modifyTime: string;
  sortOrder: number;
}

const MOCK: Activity[] = [
  { id: 1, name: '金秋国庆一起远行', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/autumn', status: 'published', views: 105, viewers: 55, shares: 0, startTime: '2026-08-25 18:01:32', endTime: '长期有效', creator: '屈艺', createTime: '2026-08-25 18:01:32', modifier: '屈艺', modifyTime: '2026-08-25 18:01:32', sortOrder: 99 },
  { id: 2, name: '澳大利亚 新西兰 全景深度游', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/au-nz', status: 'published', views: 66, viewers: 36, shares: 0, startTime: '2026-08-22 10:24:16', endTime: '2026-09-30 23:59:59', creator: '屈艺', createTime: '2026-08-22 10:24:16', modifier: '白云鹏', modifyTime: '2026-08-24 09:12:03', sortOrder: 98 },
  { id: 3, name: '欧洲五国夏日限定', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/europe', status: 'published', views: 88, viewers: 41, shares: 2, startTime: '2026-08-18 15:40:00', endTime: '长期有效', creator: '白云鹏', createTime: '2026-08-18 15:40:00', modifier: '白云鹏', modifyTime: '2026-08-20 14:05:44', sortOrder: 97 },
  { id: 4, name: '海岛度假季 一价全含', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/island', status: 'published', views: 42, viewers: 28, shares: 0, startTime: '2026-08-15 09:00:00', endTime: '2026-10-07 23:59:59', creator: '屈艺', createTime: '2026-08-15 09:00:00', modifier: '屈艺', modifyTime: '2026-08-16 11:30:20', sortOrder: 96 },
  { id: 5, name: '亲子研学 走进丝绸之路', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/silk-road', status: 'unpublished', views: 0, viewers: 0, shares: 0, startTime: '2026-09-01 00:00:00', endTime: '长期有效', creator: '白云鹏', createTime: '2026-08-26 11:20:00', modifier: '白云鹏', modifyTime: '2026-08-26 11:20:00', sortOrder: 95 },
  { id: 6, name: '十一黄金周 机票酒店直减', type: 'C端活动', scope: '全部', link: 'https://activity.uzai.com/activity/national-day', status: 'offline', views: 12, viewers: 9, shares: 0, startTime: '2026-07-01 00:00:00', endTime: '2026-08-31 23:59:59', creator: '屈艺', createTime: '2026-07-01 00:00:00', modifier: '屈艺', modifyTime: '2026-08-20 08:00:00', sortOrder: 94 },
];

const STATUS_META: Record<Activity['status'], { label: string; cls: string; dot: string }> = {
  published: { label: '已发布', cls: 'bg-green-50 text-green-600', dot: 'bg-green-500' },
  unpublished: { label: '未发布', cls: 'bg-amber-50 text-amber-600', dot: 'bg-amber-500' },
  offline: { label: '已下线', cls: 'bg-gray-100 text-gray-500', dot: 'bg-gray-400' },
};

const TopicActivity = () => {
  const navigate = useNavigate();
  const [keyword, setKeyword] = useState('');
  const [type, setType] = useState('C端活动');
  const [status, setStatus] = useState('');
  const [list, setList] = useState<Activity[]>(MOCK);
  const [copied, setCopied] = useState<string | null>(null);

  const filtered = useMemo(() => {
    return list.filter((a) => {
      if (keyword && !a.name.includes(keyword)) return false;
      if (type && a.type !== type) return false;
      if (status && a.status !== status) return false;
      return true;
    });
  }, [list, keyword, type, status]);

  const doCopy = (text: string, key: string) => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).catch(() => undefined);
    }
    setCopied(key);
    setTimeout(() => setCopied(null), 1500);
  };

  const handleDelete = (a: Activity) => {
    if (!confirm(`确定删除「${a.name}」吗？`)) return;
    setList((prev) => prev.filter((x) => x.id !== a.id));
  };

  return (
    <div className="flex min-h-screen bg-gray-100">
      {!isEmbed && <Sidebar />}
      <div className="flex-1 flex flex-col overflow-hidden">
        {!isEmbed && <TopBar />}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* 面包屑 */}
          <div className="px-6 py-3 bg-white border-b border-gray-100 flex-shrink-0">
            <nav className="flex items-center text-xs text-gray-500">
              <span className="hover:text-gray-700 cursor-pointer" onClick={() => navigate('/admin')}>运营管理</span>
              <span className="mx-1.5 text-gray-400">〉</span>
              <span className="text-gray-700">营销活动</span>
              <span className="mx-1.5 text-gray-400">〉</span>
              <span className="text-gray-800 font-medium">C端专题活动</span>
            </nav>
          </div>

          <div className="flex-1 overflow-auto">
            <div className="bg-white">
              {/* 标题栏 */}
              <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
                <h3 className="text-sm font-bold text-gray-800">全部活动页</h3>
                <button
                  onClick={() => navigate('/admin/topic-activity/edit')}
                  className="flex items-center gap-1 px-3 py-1.5 bg-gradient-to-b from-[#ff4d6d] to-[#ff003c] text-white text-sm rounded hover:shadow-lg hover:shadow-red-200 transition-all"
                >
                  <Plus className="w-4 h-4" />
                  新增
                </button>
              </div>

              {/* 筛选区 */}
              <div className="border-b border-gray-200 px-4 py-3 flex items-center gap-3 bg-gray-50">
                <input
                  type="text"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && setKeyword(keyword)}
                  placeholder="请输入活动名称"
                  className="h-8 w-48 px-3 border border-gray-300 rounded text-xs bg-white focus:outline-none focus:border-red-400"
                />
                <select
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="h-8 px-2 border border-gray-300 rounded text-xs bg-white focus:outline-none focus:border-red-400"
                >
                  <option value="">请选择活动类型</option>
                  <option value="C端活动">C端活动</option>
                  <option value="B端活动">B端活动</option>
                </select>
                <select
                  value={status}
                  onChange={(e) => setStatus(e.target.value)}
                  className="h-8 px-2 border border-gray-300 rounded text-xs bg-white focus:outline-none focus:border-red-400"
                >
                  <option value="">请选择状态</option>
                  <option value="published">已发布</option>
                  <option value="unpublished">未发布</option>
                  <option value="offline">已下线</option>
                </select>
                <button
                  onClick={() => { setKeyword(''); setType('C端活动'); setStatus(''); }}
                  className="h-8 px-3 border border-gray-300 text-gray-600 text-xs rounded hover:bg-gray-100 flex items-center gap-1"
                >
                  <RotateCcw className="w-3 h-3" />
                  清空
                </button>
                <button className="h-8 px-4 bg-gradient-to-b from-[#ff4d6d] to-[#ff003c] text-white text-xs rounded hover:shadow-lg hover:shadow-red-200 flex items-center gap-1">
                  <Search className="w-3 h-3" />
                  查询
                </button>
              </div>

              {/* 表格 */}
              <div className="overflow-x-auto">
                <table className="w-full border-collapse min-w-[1500px]">
                  <thead>
                    <tr style={{ backgroundColor: '#f3f5fc' }}>
                      {['序号', '活动名称', '活动类型', '适用范围', '活动链接', '状态', '浏览次数', '浏览人数', '分享人数', '生效时间', '失效时间', '创建人', '创建时间', '最近操作人', '最近操作时间', '排序', '操作'].map((h, i) => (
                        <th
                          key={h}
                          className="px-3 py-2.5 text-left text-xs font-medium text-gray-600 whitespace-nowrap"
                          style={{ borderRight: i < 16 ? '1px solid #e8ebf5' : 'none' }}
                        >
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.length === 0 ? (
                      <tr>
                        <td colSpan={17} className="px-4 py-10 text-center text-gray-500 text-xs">暂无数据</td>
                      </tr>
                    ) : (
                      filtered.map((a, index) => {
                        const sm = STATUS_META[a.status];
                        return (
                          <tr key={a.id} className={index % 2 === 1 ? 'bg-[#fafbfd]' : 'bg-white'}>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.id}</td>
                            <td className="px-3 py-3 text-xs text-gray-700 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.name}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.type}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.scope}</td>
                            <td className="px-3 py-3 text-xs whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>
                              <span className="text-blue-500 max-w-[180px] truncate inline-block align-middle">{a.link}</span>
                            </td>
                            <td className="px-3 py-3 text-xs whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>
                              <span className={`inline-flex items-center gap-1 px-2 py-0.5 ${sm.cls} rounded text-xs`}>
                                <span className={`w-1.5 h-1.5 rounded-full ${sm.dot}`} />
                                {sm.label}
                              </span>
                            </td>
                            <td className="px-3 py-3 text-xs text-gray-700 font-mono whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.views}</td>
                            <td className="px-3 py-3 text-xs text-gray-700 font-mono whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.viewers}</td>
                            <td className="px-3 py-3 text-xs text-gray-700 font-mono whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.shares}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.startTime}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.endTime}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.creator}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.createTime}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.modifier}</td>
                            <td className="px-3 py-3 text-xs text-gray-600 whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>{a.modifyTime}</td>
                            <td className="px-3 py-3 text-xs whitespace-nowrap" style={{ borderRight: '1px solid #f0f0f0' }}>
                              <span className="inline-block min-w-[28px] px-1.5 h-6 leading-6 text-center bg-gray-50 border border-gray-200 rounded text-gray-700 font-mono">{a.sortOrder}</span>
                            </td>
                            <td className="px-3 py-3 text-xs whitespace-nowrap">
                              <div className="flex gap-2 items-center">
                                <button onClick={() => navigate(`/admin/topic-activity/edit/${a.id}`)} className="inline-flex items-center gap-0.5 text-gray-500 hover:text-gray-700"><Eye className="w-3 h-3" />查看</button>
                                <button onClick={() => navigate(`/admin/topic-activity/edit/${a.id}`)} className="inline-flex items-center gap-0.5 text-[#ed1e4e] hover:text-[#c41840] font-medium"><Edit3 className="w-3 h-3" />编辑</button>
                                <button onClick={() => navigate(`/admin/topic-activity/edit?copy=${a.id}`)} className="inline-flex items-center gap-0.5 text-gray-500 hover:text-[#ed1e4e]"><Copy className="w-3 h-3" />复制活动配置</button>
                                <button onClick={() => doCopy(a.link, `link-${a.id}`)} className="inline-flex items-center gap-0.5 text-gray-500 hover:text-[#ed1e4e]">
                                  {copied === `link-${a.id}` ? <Check className="w-3 h-3 text-green-500" /> : <Link2 className="w-3 h-3" />}
                                  {copied === `link-${a.id}` ? '已复制' : '复制链接'}
                                </button>
                                <button onClick={() => doCopy(a.link.replace('activity.uzai.com', 'mp.uzai.com'), `mp-${a.id}`)} className="inline-flex items-center gap-0.5 text-gray-500 hover:text-[#ed1e4e]">
                                  {copied === `mp-${a.id}` ? <Check className="w-3 h-3 text-green-500" /> : <Link2 className="w-3 h-3" />}
                                  {copied === `mp-${a.id}` ? '已复制' : '复制小程序链接'}
                                </button>
                                <button onClick={() => handleDelete(a)} className="inline-flex items-center gap-0.5 text-gray-500 hover:text-red-500"><Trash2 className="w-3 h-3" />删除</button>
                              </div>
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>

              <Pagination total={filtered.length} page={1} pageSize={20} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TopicActivity;