const ValueCard = ({ tone, icon, title, metric, desc }: { tone: 'red' | 'amber' | 'blue' | 'green'; icon: React.ReactNode; title: string; metric: string; desc: string }) => {
  const toneMap = {
    red: 'border-red-200 bg-red-50/40',
    amber: 'border-amber-200 bg-amber-50/40',
    blue: 'border-blue-200 bg-blue-50/40',
    green: 'border-green-200 bg-green-50/40',
  };
  const textMap = {
    red: 'text-red-600',
    amber: 'text-amber-600',
    blue: 'text-blue-600',
    green: 'text-green-600',
  };
  return (
    <div className={'rounded-xl border p-4 ' + toneMap[tone]}>
      <div className="flex items-center gap-2 mb-2">
        <span className={textMap[tone]}>{icon}</span>
        <span className="text-sm font-bold text-gray-800">{title}</span>
      </div>
      <div className={'text-2xl font-black mb-1.5 ' + textMap[tone]}>{metric}</div>
      <p className="text-xs text-gray-600 leading-relaxed">{desc}</p>
    </div>
  );
};

const ROI = ({ k, before, after, delta }: { k: string; before: string; after: string; delta: string }) => (
  <tr>
    <td className="px-3 py-2 text-gray-700 font-medium">{k}</td>
    <td className="px-3 py-2 text-gray-500">{before}</td>
    <td className="px-3 py-2 text-gray-800">{after}</td>
    <td className={'px-3 py-2 font-bold ' + (delta.startsWith('-') ? 'text-green-600' : delta.startsWith('+') ? 'text-red-500' : 'text-blue-500')}>{delta}</td>
  </tr>
);

const RoadmapCard = ({ phase, title, tone, children }: { phase: string; title: string; tone: 'red' | 'blue' | 'amber'; children: React.ReactNode }) => {
  const map = {
    red: 'border-red-200 bg-red-50/30',
    blue: 'border-blue-200 bg-blue-50/30',
    amber: 'border-amber-200 bg-amber-50/30',
  };
  return (
    <div className={'rounded-xl border p-4 ' + map[tone]}>
      <div className="flex items-baseline justify-between mb-3">
        <span className="text-xs font-bold text-gray-400">{phase}</span>
        <span className="text-sm font-bold text-gray-800">{title}</span>
      </div>
      <ul className="space-y-1.5 text-xs text-gray-700">{children}</ul>
    </div>
  );
};

const RoadmapItem = ({ children }: { children: React.ReactNode }) => (
  <li className="flex items-start gap-2">
    <span className="w-1.5 h-1.5 rounded-full bg-red-400 mt-1.5 flex-shrink-0" />
    <span>{children}</span>
  </li>
);

const Scenario = ({ tone, icon, tag, role, title, trigger, flow, before, after, value }: {
  tone: 'red' | 'amber' | 'blue' | 'green';
  icon: React.ReactNode;
  tag: string;
  role: string;
  title: string;
  trigger: string;
  flow: string[];
  before: string;
  after: string;
  value: string;
}) => {
  const toneMap = {
    red: { border: 'border-red-200', tag: 'bg-red-100 text-red-700', num: 'bg-red-500' },
    amber: { border: 'border-amber-200', tag: 'bg-amber-100 text-amber-700', num: 'bg-amber-500' },
    blue: { border: 'border-blue-200', tag: 'bg-blue-100 text-blue-700', num: 'bg-blue-500' },
    green: { border: 'border-green-200', tag: 'bg-green-100 text-green-700', num: 'bg-green-500' },
  };
  const c = toneMap[tone];
  return (
    <div className={'bg-white rounded-xl border-l-4 ' + c.border + ' border-y border-r border-gray-200 p-5'}>
      <div className="flex items-start justify-between mb-3 flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <span className={'w-7 h-7 rounded-full ' + c.num + ' text-white flex items-center justify-center'}>{icon}</span>
          <h4 className="text-sm font-bold text-gray-800">{title}</h4>
        </div>
        <div className="flex items-center gap-2">
          <span className={'text-[10px] px-2 py-0.5 rounded ' + c.tag + ' font-bold'}>{tag}</span>
          <span className="text-[11px] text-gray-500">{role}</span>
        </div>
      </div>
      <div className="grid md:grid-cols-3 gap-4 text-xs">
        <div>
          <div className="text-gray-400 mb-1">▍ 触发背景</div>
          <div className="text-gray-700 leading-relaxed">{trigger}</div>
        </div>
        <div>
          <div className="text-gray-400 mb-1">▍ 用户操作链路</div>
          <ol className="space-y-0.5 text-gray-700">
            {flow.map((step, i) => (
              <li key={i} className="flex items-start gap-1.5">
                <span className={'text-[10px] w-4 h-4 rounded-full ' + c.num + ' text-white flex items-center justify-center flex-shrink-0 mt-0.5'}>{i + 1}</span>
                <span>{step}</span>
              </li>
            ))}
          </ol>
        </div>
        <div>
          <div className="text-gray-400 mb-1">▍ 业务价值</div>
          <div className="space-y-1.5">
            <div className="flex items-start gap-1.5">
              <span className="text-gray-400 line-through">{before}</span>
            </div>
            <div className="flex items-start gap-1.5">
              <span className="text-green-600 font-bold">之后：</span>
              <span className="text-gray-800">{after}</span>
            </div>
            <div className="text-gray-500 pt-1 border-t border-gray-100 leading-relaxed">{value}</div>
          </div>
        </div>
      </div>
    </div>
  );
};

