import { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import TopNav from '../components/Header/TopNav';
import MainMenu from '../components/Header/MainMenu';
import { ArrowLeft, Eye, Calendar, Tag, ChevronRight } from 'lucide-react';

interface NewsItem {
  id: number;
  title: string;
  category: string;
  summary: string;
  content: string;
  cover_image: string;
  status: string;
  creator: string;
  create_date: string;
  publish_at: string | null;
  actual_publish_at: string | null;
  pv: number;
  uv: number;
}

const API_BASE = 'http://localhost:3001/api';

const NewsDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [news, setNews] = useState<NewsItem | null>(null);
  const [related, setRelated] = useState<NewsItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    fetchDetail();
    fetchRelated();
    reportView();
    window.scrollTo(0, 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const fetchDetail = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE}/news/${id}`);
      if (res.data.code === 200) {
        setNews(res.data.data);
      } else {
        setNews(null);
      }
    } catch (error) {
      console.error('获取新闻详情失败:', error);
      setNews(null);
    }
    setLoading(false);
  };

  const fetchRelated = async () => {
    if (!news?.category) return;
    try {
      const res = await axios.get(`${API_BASE}/news`, {
        params: { page: 1, pageSize: 5, enabled: 1, category: news.category }
      });
      if (res.data.code === 200) {
        setRelated(res.data.data.list.filter((n: NewsItem) => String(n.id) !== id).slice(0, 4));
      }
    } catch (error) {
      console.error('获取相关新闻失败:', error);
    }
  };

  const reportView = () => {
    const today = new Date().toDateString();
    const uvKey = `news_uv_${id}_${today}`;
    const isUnique = !localStorage.getItem(uvKey);
    if (isUnique) localStorage.setItem(uvKey, '1');
    axios.post(`${API_BASE}/news/${id}/view`, { isUnique }).catch(() => {});
  };

  useEffect(() => {
    if (news?.category) fetchRelated();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [news?.category]);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const d = new Date(dateStr.replace(' ', 'T'));
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  // 带时分：YYYY-MM-DD HH:MM
  const formatDateTime = (dateStr: string | null | undefined) => {
    if (!dateStr) return '';
    const d = new Date(dateStr.replace(' ', 'T'));
    if (isNaN(d.getTime())) return dateStr;
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <TopNav />
        <MainMenu />
        <div className="max-w-[900px] mx-auto px-4 py-20 text-center text-gray-500">加载中...</div>
      </div>
    );
  }

  if (!news) {
    return (
      <div className="min-h-screen bg-gray-50">
        <TopNav />
        <MainMenu />
        <div className="max-w-[900px] mx-auto px-4 py-20 text-center">
          <div className="text-gray-500 mb-4">该新闻不存在或已下架</div>
          <button
            onClick={() => navigate('/news')}
            className="px-5 py-2 bg-red-500 text-white text-sm rounded hover:bg-red-600"
          >
            返回列表
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <TopNav />
      <MainMenu />

      {/* 面包屑 */}
      <div className="bg-white border-b border-gray-200">
        <div className="max-w-[900px] mx-auto px-4 py-3 flex items-center gap-2 text-xs text-gray-500">
          <Link to="/" className="hover:text-red-500">首页</Link>
          <ChevronRight className="w-3 h-3" />
          <Link to="/news" className="hover:text-red-500">众信动态</Link>
          <ChevronRight className="w-3 h-3" />
          <span className="text-gray-700 truncate">{news.title}</span>
        </div>
      </div>

      <article className="max-w-[900px] mx-auto px-4 py-10">
        {/* 标题区 */}
        <header className="mb-8">
          <div className="flex items-center gap-3 mb-4">
            <span className="px-2.5 py-1 bg-red-50 text-red-600 text-xs rounded">
              {news.category}
            </span>
            <span className="flex items-center gap-1 text-xs text-gray-500">
              <Calendar className="w-3.5 h-3.5" />
              {formatDateTime(news.create_date)}
            </span>
            <span className="flex items-center gap-1 text-xs text-gray-500">
              <Eye className="w-3.5 h-3.5" />
              {(news.pv || 0).toLocaleString()} 次浏览
            </span>
          </div>
          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 leading-tight mb-3">
            {news.title}
          </h1>
          {news.summary && (
            <p className="text-base text-gray-500 leading-relaxed border-l-4 border-red-400 pl-4 py-1 bg-red-50/40">
              {news.summary}
            </p>
          )}
          <div className="mt-4 flex items-center gap-3 text-xs text-gray-500">
            <span>作者：{news.creator}</span>
            {news.actual_publish_at && (
              <span className="flex items-center gap-1 text-gray-500">
                <Calendar className="w-3.5 h-3.5 text-red-400" />
                <span className="text-gray-400">发稿时间：</span>
                <span className="text-gray-700">{formatDateTime(news.actual_publish_at)}</span>
              </span>
            )}
          </div>
        </header>

        {/* 封面图 */}
        {news.cover_image && (
          <div className="mb-8 rounded-lg overflow-hidden">
            <img
              src={news.cover_image}
              alt={news.title}
              className="w-full max-h-[480px] object-cover"
            />
          </div>
        )}

        {/* 正文 */}
        <div
          className="prose-content text-base text-gray-800 leading-loose"
          dangerouslySetInnerHTML={{ __html: news.content || '' }}
        />

        {/* 底部操作 */}
        <div className="mt-12 pt-6 border-t border-gray-200 flex items-center justify-between">
          <button
            onClick={() => navigate('/news')}
            className="flex items-center gap-1 text-sm text-gray-600 hover:text-red-500"
          >
            <ArrowLeft className="w-4 h-4" />
            返回列表
          </button>
          <div className="text-xs text-gray-400">
            本文由众信旅游集团发布
          </div>
        </div>

        {/* 相关文章 */}
        {related.length > 0 && (
          <section className="mt-12">
            <h3 className="text-base font-bold text-gray-800 mb-4 flex items-center gap-2">
              <Tag className="w-4 h-4 text-red-500" />
              相关{news.category}
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {related.map(r => (
                <Link
                  key={r.id}
                  to={`/news/${r.id}`}
                  className="flex gap-3 p-3 bg-white border border-gray-200 rounded hover:border-red-300 hover:shadow-sm transition-all"
                >
                  <div className="w-20 h-14 flex-shrink-0 bg-gray-100 rounded overflow-hidden">
                    {r.cover_image ? (
                      <img src={r.cover_image} alt={r.title} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-gray-400 text-[10px]">无图</div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-gray-800 line-clamp-2 hover:text-red-500">{r.title}</div>
                    <div className="text-[11px] text-gray-400 mt-1">{formatDate(r.create_date)}</div>
                  </div>
                </Link>
              ))}
            </div>
          </section>
        )}
      </article>

      {/* 正文样式 */}
      <style>{`
        .prose-content { word-break: break-word; }
        .prose-content p { margin: 0 0 1em 0; }
        .prose-content h1, .prose-content h2, .prose-content h3 {
          font-weight: 700;
          color: #1f2937;
          margin: 1.4em 0 0.6em 0;
          line-height: 1.3;
        }
        .prose-content h1 { font-size: 1.75em; }
        .prose-content h2 { font-size: 1.4em; }
        .prose-content h3 { font-size: 1.2em; }
        .prose-content img { max-width: 100%; border-radius: 6px; margin: 0.8em 0; }
        .prose-content a { color: #ed1e4e; text-decoration: underline; }
        .prose-content blockquote {
          border-left: 4px solid #e5e7eb;
          padding-left: 1em;
          color: #6b7280;
          margin: 1em 0;
        }
        .prose-content pre {
          background: #1f2937;
          color: #f3f4f6;
          padding: 1em;
          border-radius: 6px;
          overflow-x: auto;
          font-size: 0.9em;
          line-height: 1.5;
        }
        .prose-content ul, .prose-content ol { padding-left: 1.5em; margin: 0 0 1em 0; }
        .prose-content ul { list-style: disc; }
        .prose-content ol { list-style: decimal; }
        .prose-content li { margin: 0.3em 0; }
        .prose-content strong { font-weight: 700; }
      `}</style>
    </div>
  );
};

export default NewsDetail;
