// ========== 工具函数 ==========
const formatDateTime = (date: Date) => {
  const pad = (n: number) => n.toString().padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
};
const formatTimeDisplay = (val: string, type: 'start' | 'end') => {
  if (!val) return type === 'start' ? '立即生效' : '长期有效';
  return val.replace('T', ' ');
};
const boolDisplay = (v: boolean) => v ? '开启' : '关闭';
const getPlatformsDisplay = (cfg: GrayScreenConfig): string => {
  const list: string[] = [];
  if (cfg.youzaiMiniProgram) list.push('悠哉C端小程序');
  if (cfg.feizhuMiniProgram) list.push('飞猪C端小程序');
  if (cfg.youzaiWebsite) list.push('悠哉官网');
  return list.length ? list.join('、') : '无';
};
const getActivePlatforms = (cfg: GrayScreenConfig): string[] => {
  const result: string[] = [];
  if (cfg.youzaiMiniProgram) result.push('悠哉C端小程序');
  if (cfg.feizhuMiniProgram) result.push('飞猪C端小程序');
  if (cfg.youzaiWebsite) result.push('悠哉官网');
  return result;
};

// 计算所有变更字段
const computeChangedFields = (oldCfg: GrayScreenConfig, newCfg: GrayScreenConfig, actionType: 'open' | 'close' | 'modify'): ChangedField[] => {
  const fields: ChangedField[] = [];
  const platformKeys: Array<{ key: keyof GrayScreenConfig; label: string }> = [
    { key: 'youzaiMiniProgram', label: '悠哉C端小程序' },
    { key: 'feizhuMiniProgram', label: '飞猪C端小程序' },
    { key: 'youzaiWebsite', label: '悠哉官网' },
  ];

  const oldPlat = getPlatformsDisplay(oldCfg);
  const newPlat = getPlatformsDisplay(newCfg);
  if (oldPlat !== newPlat) {
    fields.push({ field: '启用平台（总览）', oldValue: oldPlat, newValue: newPlat });
  } else if (actionType === 'modify') {
    fields.push({ field: '启用平台（总览）', oldValue: oldPlat, newValue: `${newPlat}（未变更）` });
  }

  platformKeys.forEach(({ key, label }) => {
    const oldVal = oldCfg[key] as boolean;
    const newVal = newCfg[key] as boolean;
    if (actionType === 'modify') {
      if (oldVal === newVal) {
        fields.push({ field: `平台开关・${label}`, oldValue: boolDisplay(oldVal), newValue: `${boolDisplay(newVal)}（未变更）` });
      } else {
        fields.push({ field: `平台开关・${label}`, oldValue: boolDisplay(oldVal), newValue: boolDisplay(newVal) });
      }
    } else {
      if (oldVal !== newVal) {
        fields.push({ field: `平台开关・${label}`, oldValue: boolDisplay(oldVal), newValue: boolDisplay(newVal) });
      }
    }
  });

  const oldReason = oldCfg.reason || '(未填写)';
  const newReason = newCfg.reason || '(未填写)';
  if (oldReason !== newReason) {
    fields.push({ field: '灰屏原因', oldValue: oldReason, newValue: newReason });
  } else if (actionType === 'modify' && oldReason) {
    fields.push({ field: '灰屏原因', oldValue: oldReason, newValue: `${newReason}（未变更）` });
  }

  const oldStart = formatTimeDisplay(oldCfg.startTime, 'start');
  const newStart = formatTimeDisplay(newCfg.startTime, 'start');
  if (oldStart !== newStart) {
    fields.push({ field: '开始时间', oldValue: oldStart, newValue: newStart });
  } else if (actionType === 'modify') {
    fields.push({ field: '开始时间', oldValue: oldStart, newValue: `${newStart}（未变更）` });
  }

  const oldEnd = formatTimeDisplay(oldCfg.endTime, 'end');
  const newEnd = formatTimeDisplay(newCfg.endTime, 'end');
  if (oldEnd !== newEnd) {
    fields.push({ field: '结束时间', oldValue: oldEnd, newValue: newEnd });
  } else if (actionType === 'modify') {
    fields.push({ field: '结束时间', oldValue: oldEnd, newValue: `${newEnd}（未变更）` });
  }

  return fields;
};

// 将 changedFields 转成一段文字描述
const formatChangedFieldsText = (fields: ChangedField[]): string => {
  // 只取实际发生了变化的字段（不含"未变更"）
  const changed = fields.filter(f => !f.newValue.includes('未变更'));
  if (changed.length === 0) return '无实际变更';

  const parts: string[] = [];
  let platformSummary = '';
  const timeChanges: string[] = [];
  let reasonChange = '';

  changed.forEach(cf => {
    if (cf.field === '启用平台（总览）') {
      platformSummary = `启用平台从「${cf.oldValue}」调整为「${cf.newValue}」`;
    } else if (cf.field.startsWith('平台开关・')) {
      const platName = cf.field.replace('平台开关・', '');
      if (cf.newValue === '开启') {
        parts.push(`开启「${platName}」`);
      } else if (cf.newValue === '关闭') {
        parts.push(`关闭「${platName}」`);
      }
    } else if (cf.field === '灰屏原因') {
      reasonChange = `原因从「${cf.oldValue}」更新为「${cf.newValue}」`;
    } else if (cf.field === '开始时间') {
      timeChanges.push(`开始时间从「${cf.oldValue}」调整为「${cf.newValue}」`);
    } else if (cf.field === '结束时间') {
      timeChanges.push(`结束时间从「${cf.oldValue}」调整为「${cf.newValue}」`);
    }
  });

  const result: string[] = [];
  if (platformSummary) result.push(platformSummary);
  if (parts.length > 0) result.push(parts.join('；'));
  if (reasonChange) result.push(reasonChange);
  if (timeChanges.length > 0) result.push(timeChanges.join('；'));

  return result.length > 0 ? result.join('；') : '无实际变更';
};

// 补全旧日志的 changedFields（迁移用）
const migrateLogAddChangedFields = (log: OperationLog): OperationLog => {
  if (log.changedFields && log.changedFields.length > 0) return log;
  // 旧数据没有 changedFields，根据现有字段尽量补全
  const fields: ChangedField[] = [];
  if (log.action === 'modify') {
    // modify 场景：补全所有字段
    const prev = log.previousPlatforms || [];
    const curr = log.platforms || [];
    fields.push({
      field: '启用平台（总览）',
      oldValue: prev.length ? prev.join('、') : '无',
      newValue: curr.length ? curr.join('、') : '无',
    });
    const allPlatforms = ['悠哉C端小程序', '飞猪C端小程序', '悠哉官网'];
    allPlatforms.forEach(p => {
      const wasOn = prev.includes(p);
      const isOn = curr.includes(p);
      const unchanged = wasOn === isOn;
      fields.push({
        field: `平台开关・${p}`,
        oldValue: boolDisplay(wasOn),
        newValue: unchanged ? `${boolDisplay(isOn)}（未变更）` : boolDisplay(isOn),
      });
    });
    fields.push({ field: '灰屏原因', oldValue: log.reason, newValue: `${log.reason}（未变更）` });
    fields.push({ field: '开始时间', oldValue: '—', newValue: '—（未变更）' });
    fields.push({ field: '结束时间', oldValue: '—', newValue: '—（未变更）' });
  } else if (log.action === 'open') {
    fields.push({ field: '启用平台（总览）', oldValue: '无', newValue: (log.platforms || []).join('、') });
    (log.platforms || []).forEach(p => {
      fields.push({ field: `平台开关・${p}`, oldValue: '关闭', newValue: '开启' });
    });
    fields.push({ field: '灰屏原因', oldValue: '(未填写)', newValue: log.reason });
  } else if (log.action === 'close') {
    fields.push({ field: '启用平台（总览）', oldValue: (log.previousPlatforms || []).join('、'), newValue: '无' });
    (log.previousPlatforms || []).forEach(p => {
      fields.push({ field: `平台开关・${p}`, oldValue: '开启', newValue: '关闭' });
    });
    fields.push({ field: '灰屏原因', oldValue: log.reason, newValue: log.reason });
  }
  return { ...log, changedFields: fields };
};

