const GrayScreenModal = ({ open, onClose, onSave }: GrayScreenModalProps) => {
  const [activeTab, setActiveTab] = useState<TabKey>('grayscale');
  const [saved, setSaved] = useState(false);

  const [config, setConfig] = useState<GrayScreenConfig>(defaultConfig);
  const [previousConfig, setPreviousConfig] = useState<GrayScreenConfig>(defaultConfig);
  const [logs, setLogs] = useState<OperationLog[]>([]);
  const [showLogs, setShowLogs] = useState(true);

  const tabs: TabItem[] = [
    { key: 'grayscale', name: '首页灰屏设置', desc: '特殊悼念场景全站灰屏控制', icon: Layers, color: '#4b5563', status: 'enabled' },
    { key: 'coming', name: '更多配置（敬请期待）', desc: 'Banner / 公告 / 金刚区 等', icon: Sparkles, color: '#6b7280', status: 'coming' },
  ];

  const platformItems = [
    { key: 'youzaiMiniProgram' as const, name: '悠哉C端小程序', desc: '微信小程序首页灰屏显示', icon: Smartphone, color: '#07C160' },
    { key: 'feizhuMiniProgram' as const, name: '飞猪C端小程序', desc: '飞猪小程序首页灰屏显示', icon: Smartphone, color: '#FF6A00' },
    { key: 'youzaiWebsite' as const, name: '悠哉官网', desc: 'PC官网全站灰屏显示', icon: Monitor, color: '#1677FF' },
  ];

  useEffect(() => {
    if (!open) return;
    setSaved(false);
    setActiveTab('grayscale');
    setShowLogs(true);

    // 配置
    const savedConfig = localStorage.getItem(CONFIG_STORAGE_KEY);
    if (savedConfig) {
      try {
        const parsed = JSON.parse(savedConfig);
        setConfig(parsed);
        setPreviousConfig(parsed);
      } catch {
        setConfig(defaultConfig);
        setPreviousConfig(defaultConfig);
      }
    } else {
      setConfig(defaultConfig);
      setPreviousConfig(defaultConfig);
    }

    // 日志：检查版本号，旧版本自动迁移/重置
    const schemaVer = localStorage.getItem(SCHEMA_VERSION_KEY);
    if (schemaVer !== String(CURRENT_SCHEMA_VERSION)) {
      // 版本不匹配 → 用最新 mock 覆盖
      setLogs(initialMockLogs);
      localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(initialMockLogs));
      localStorage.setItem(SCHEMA_VERSION_KEY, String(CURRENT_SCHEMA_VERSION));
    } else {
      // 新版本 → 读取本地存储（如果有），并确保每条日志都有 changedFields
      const savedLogs = localStorage.getItem(LOG_STORAGE_KEY);
      if (savedLogs) {
        try {
          const parsed = JSON.parse(savedLogs);
          if (Array.isArray(parsed) && parsed.length > 0) {
            const migrated = parsed.map(migrateLogAddChangedFields);
            setLogs(migrated);
            // 存回迁移后的数据
            localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(migrated));
            return;
          }
        } catch {
          // ignore
        }
      }
      setLogs(initialMockLogs);
      localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(initialMockLogs));
    }
  }, [open]);

  if (!open) return null;

  const getActionBadgeStyle = (action: OperationLog['action']) => {
    switch (action) {
      case 'open': return 'bg-gray-700 text-white';
      case 'close': return 'bg-green-100 text-green-700 border border-green-200';
      case 'modify': return 'bg-amber-50 text-amber-700 border border-amber-200';
    }
  };

  const handleTogglePlatform = (key: keyof Pick<GrayScreenConfig, 'youzaiMiniProgram' | 'feizhuMiniProgram' | 'youzaiWebsite'>) => {
    setConfig(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSaveAll = () => {
    const nowActive = getActivePlatforms(config);
    const prevActive = getActivePlatforms(previousConfig);
    const now = new Date();

    let action: 'open' | 'close' | 'modify' = 'modify';
    let actionText = '调整配置';
    if (prevActive.length === 0 && nowActive.length > 0) { action = 'open'; actionText = '开启灰屏'; }
    else if (prevActive.length > 0 && nowActive.length === 0) { action = 'close'; actionText = '关闭灰屏'; }

    const changedFields = computeChangedFields(previousConfig, config, action);

    const newLog: OperationLog = {
      id: Date.now(), operator: '唐美芳', time: formatDateTime(now), action, actionText,
      reason: config.reason || '(未填写原因)', platforms: nowActive, previousPlatforms: prevActive, changedFields,
    };
    const updatedLogs = [newLog, ...logs];
    setLogs(updatedLogs);
    localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(updatedLogs));
    localStorage.setItem(SCHEMA_VERSION_KEY, String(CURRENT_SCHEMA_VERSION));
    localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config));
    setPreviousConfig(config);

    setSaved(true);
    onSave(config);
    setTimeout(() => { onClose(); }, 900);
  };

  const statusPillClass = (s: TabItem['status']) =>
    s === 'enabled' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-500 border-gray-200';
  const statusPillText = (s: TabItem['status']) => s === 'enabled' ? '已上线' : '敬请期待';

  const currentTab = tabs.find(t => t.key === activeTab)!;
  const canSave = currentTab.status === 'enabled';

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />

      <div className="relative w-[780px] max-h-[90vh] bg-white rounded-xl shadow-2xl overflow-hidden animate-[fadeIn_0.2s_ease-out] flex flex-col">
        {/* ===== 头部 ===== */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-gradient-to-r from-[#fff5f7] to-white flex-shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-lg bg-[#ed1e4e]/10 flex items-center justify-center">
              <Zap className="w-[18px] h-[18px] text-[#ed1e4e]" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-gray-800">动态配置中心</h3>
              <p className="text-xs text-gray-500 mt-0.5">集中管理 C 端首页的动态配置项，实时生效</p>
            </div>
          </div>
          <button onClick={onClose} className="w-8 h-8 rounded-lg hover:bg-gray-100 flex items-center justify-center transition-colors">
            <X className="w-4 h-4 text-gray-500" />
          </button>
        </div>

        {/* ===== Tab 栏 ===== */}
        <div className="px-6 pt-4 border-b border-gray-100 bg-gray-50/40 flex-shrink-0">
          <div className="flex items-stretch gap-2">
            {tabs.map((t) => {
              const Icon = t.icon;
              const isActive = activeTab === t.key;
              const coming = t.status === 'coming';
              return (
                <button
                  key={t.key}
                  onClick={() => setActiveTab(t.key)}
                  className={`relative group flex-1 min-w-[200px] flex items-start gap-3 px-4 py-3 rounded-t-lg border transition-all duration-200 ${
                    isActive
                      ? 'bg-white border-white border-b-white text-gray-800 shadow-[0_-1px_2px_rgba(0,0,0,0.04)]'
                      : 'bg-gray-50 border-transparent text-gray-500 hover:bg-gray-100 hover:text-gray-700'
                  }`}
                  style={isActive ? { marginBottom: '-1px', borderBottom: '1px solid #fff' } : {}}
                >
                  <div
                    className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${
                      isActive ? 'opacity-100' : 'opacity-60'
                    }`}
                    style={{ backgroundColor: isActive ? `${t.color}15` : 'transparent', color: t.color }}
                  >
                    <Icon className="w-4 h-4" />
                  </div>
                  <div className="flex-1 min-w-0 text-left">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <span className={`text-sm ${isActive ? 'font-semibold' : 'font-medium'}`}>{t.name}</span>
                      <span className={`text-[10px] px-1.5 py-0.5 rounded border ${statusPillClass(t.status)}`}>
                        {statusPillText(t.status)}
                      </span>
                    </div>
                    <div className="text-[11px] text-gray-400 mt-0.5 leading-tight">{t.desc}</div>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* ===== 内容区 ===== */}
        <div className="px-6 py-5 overflow-y-auto flex-1">
          {/* Tab1：首页灰屏设置 */}
          {activeTab === 'grayscale' && (
            <div className="space-y-5">
              {/* 顶部信息条 */}
              <div className="flex items-center justify-between px-4 py-3 rounded-xl bg-gray-50 border border-gray-200">
                <div className="flex items-center gap-2.5">
                  <div className={`w-2.5 h-2.5 rounded-full ${getActivePlatforms(config).length > 0 ? 'bg-green-500 animate-pulse' : 'bg-gray-300'}`} />
                  <div className="text-xs text-gray-600">
                    <span className="font-medium text-gray-800">当前状态：</span>
                    {getActivePlatforms(config).length > 0 ? (
                      <span>
                        灰屏 <span className="text-gray-800 font-medium">已启用</span>，生效平台
                        <span className="text-gray-800 font-medium"> {getActivePlatforms(config).length}</span> 个
                      </span>
                    ) : (
                      <span>灰屏 <span className="text-gray-500">未启用</span>，各端正常显示</span>
                    )}
                  </div>
                </div>
                <span className={`text-[11px] px-2 py-0.5 rounded border ${statusPillClass('enabled')}`}>
                  {statusPillText('enabled')}
                </span>
              </div>

              {/* 启用平台 */}
              <div>
                <div className="flex items-center gap-1 mb-3">
                  <span className="text-sm font-medium text-gray-700">启用平台</span>
                  <span className="text-red-500 text-xs">*</span>
                </div>
                <div className="space-y-3">
                  {platformItems.map((item) => {
                    const Icon = item.icon;
                    const isActive = config[item.key];
                    return (
                      <div
                        key={item.key}
                        onClick={() => handleTogglePlatform(item.key)}
                        className={`flex items-center justify-between p-4 rounded-xl border transition-all duration-200 cursor-pointer ${
                          isActive ? 'border-[#ed1e4e]/30 bg-[#fff5f7] shadow-sm' : 'border-gray-200 bg-white hover:border-gray-300 hover:bg-gray-50'
                        }`}
                      >
                        <div className="flex items-center gap-3">
                          <div
                            className={`w-10 h-10 rounded-xl flex items-center justify-center ${isActive ? 'opacity-100' : 'opacity-60'}`}
                            style={{ backgroundColor: `${item.color}15` }}
                          >
                            <Icon className="w-5 h-5" style={{ color: item.color }} />
                          </div>
                          <div>
                            <div className={`text-sm font-medium ${isActive ? 'text-gray-800' : 'text-gray-600'}`}>{item.name}</div>
                            <div className="text-xs text-gray-400 mt-0.5">{item.desc}</div>
                          </div>
                        </div>
                        <ToggleSwitch checked={isActive} onChange={() => handleTogglePlatform(item.key)} />
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* 生效时间 */}
              <div>
                <div className="flex items-center gap-1 mb-3"><span className="text-sm font-medium text-gray-700">生效时间</span></div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs text-gray-500 mb-1.5 block">开始时间</label>
                    <input
                      type="datetime-local" value={config.startTime}
                      onChange={(e) => setConfig(prev => ({ ...prev, startTime: e.target.value }))}
                      className="w-full h-9 px-3 rounded-lg border border-gray-300 text-xs focus:outline-none focus:border-[#ed1e4e] focus:ring-1 focus:ring-[#ed1e4e]/20 bg-white"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 mb-1.5 block">结束时间</label>
                    <input
                      type="datetime-local" value={config.endTime}
                      onChange={(e) => setConfig(prev => ({ ...prev, endTime: e.target.value }))}
                      className="w-full h-9 px-3 rounded-lg border border-gray-300 text-xs focus:outline-none focus:border-[#ed1e4e] focus:ring-1 focus:ring-[#ed1e4e]/20 bg-white"
                    />
                  </div>
                </div>
                <div className="flex items-center gap-1.5 mt-2 text-xs text-gray-400">
                  <div className="w-1 h-1 rounded-full bg-gray-300" />
                  <span>留空表示立即生效 / 长期有效</span>
                </div>
              </div>

              {/* 灰屏原因 */}
              <div>
                <div className="flex items-center gap-1 mb-3">
                  <span className="text-sm font-medium text-gray-700">灰屏原因</span>
                  <span className="text-red-500 text-xs">*</span>
                </div>
                <textarea
                  value={config.reason} rows={3}
                  onChange={(e) => setConfig(prev => ({ ...prev, reason: e.target.value }))}
                  placeholder="请输入灰屏原因，例如：XXX同志逝世，全站致哀..."
                  className="w-full px-3 py-2.5 rounded-lg border border-gray-300 text-xs placeholder:text-gray-400 focus:outline-none focus:border-[#ed1e4e] focus:ring-1 focus:ring-[#ed1e4e]/20 resize-none bg-white"
                />
              </div>

              {/* 操作日志（表格形式） */}
              <div className="rounded-xl border border-gray-200 overflow-hidden">
                <button
                  onClick={() => setShowLogs(!showLogs)}
                  className="w-full flex items-center justify-between px-4 py-3 bg-gray-50 hover:bg-gray-100 transition-colors"
                >
                  <div className="flex items-center gap-2">
                    <div className="w-6 h-6 rounded-md bg-[#ed1e4e]/10 flex items-center justify-center">
                      <History className="w-3.5 h-3.5 text-[#ed1e4e]" />
                    </div>
                    <span className="text-sm font-medium text-gray-700">操作日志</span>
                    <span className="text-xs text-gray-400">（共 {logs.length} 条）</span>
                  </div>
                  {showLogs ? <ChevronUp className="w-4 h-4 text-gray-400" /> : <ChevronDown className="w-4 h-4 text-gray-400" />}
                </button>
                {showLogs && (
                  <div className="max-h-[400px] overflow-y-auto">
                    {logs.length === 0 ? (
                      <div className="px-4 py-8 text-center text-xs text-gray-400">暂无操作记录</div>
                    ) : (
                      <table className="w-full text-xs border-collapse">
                        <thead className="sticky top-0 z-10">
                          <tr className="bg-gray-100 text-gray-500">
                            <th className="text-left font-medium px-4 py-2.5 whitespace-nowrap w-[150px]">操作时间</th>
                            <th className="text-left font-medium px-4 py-2.5 whitespace-nowrap w-[80px]">操作人</th>
                            <th className="text-left font-medium px-4 py-2.5">操作内容</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                          {logs.map((log) => (
                            <tr key={log.id} className="align-top hover:bg-gray-50/70 transition-colors">
                              {/* 操作时间 */}
                              <td className="px-4 py-3 text-gray-500 whitespace-nowrap">{log.time}</td>
                              {/* 操作人 */}
                              <td className="px-4 py-3 text-gray-700 font-medium whitespace-nowrap">{log.operator}</td>
                              {/* 操作内容：类型标签 + 原因 + 字段变更文字描述 */}
                              <td className="px-4 py-3">
                                <div className="flex items-center gap-2 mb-1 flex-wrap">
                                  <span className={`text-[11px] px-2 py-0.5 rounded-full font-medium ${getActionBadgeStyle(log.action)}`}>
                                    {log.actionText}
                                  </span>
                                  {log.reason && (
                                    <span className="text-gray-600">{log.reason}</span>
                                  )}
                                </div>
                                {log.changedFields && log.changedFields.length > 0 && (
                                  <div className="text-xs text-gray-500 leading-relaxed">
                                    {formatChangedFieldsText(log.changedFields)}
                                  </div>
                                )}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Tab2：敬请期待 */}
          {activeTab === 'coming' && <ComingSoonBlock />}
        </div>

        {/* ===== 底部按钮 ===== */}
        <div className="flex items-center justify-between gap-3 px-6 py-4 border-t border-gray-100 bg-gray-50/50 flex-shrink-0">
          <div className="flex items-center gap-2">
            <span className={`inline-flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-full border ${
              currentTab.status === 'enabled'
                ? 'bg-green-50 text-green-700 border-green-200'
                : 'bg-gray-100 text-gray-500 border-gray-200'
            }`}>
              <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: currentTab.color }} />
              当前 Tab：{currentTab.name} · {statusPillText(currentTab.status)}
            </span>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={onClose}
              className="h-9 px-5 rounded-lg border border-gray-300 text-xs text-gray-600 hover:bg-white hover:border-gray-400 transition-colors"
            >
              取消
            </button>
            {canSave ? (
              <button
                onClick={handleSaveAll}
                className={`h-9 px-6 rounded-lg text-xs text-white font-medium transition-all flex items-center gap-1.5 ${
                  saved ? 'bg-green-500' : 'bg-gradient-to-r from-[#ff4d6d] to-[#ff003c] hover:shadow-lg hover:shadow-[#ff003c]/25'
                }`}
              >
                {saved ? (
                  <>
                    <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                      <path d="M20 6L9 17l-5-5" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    已保存
                  </>
                ) : '保存配置'}
              </button>
            ) : (
              <button
                disabled
                className="h-9 px-6 rounded-lg text-xs text-gray-400 font-medium bg-gray-200 cursor-not-allowed flex items-center gap-1.5"
              >
                <Sparkles className="w-3.5 h-3.5" />
                敬请期待
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default GrayScreenModal;
