import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import TopNav from '../components/Header/TopNav';
import MainMenu from '../components/Header/MainMenu';
import { Search, RefreshCw, Eye, ChevronRight } from 'lucide-react';

interface NewsItem {
  id: number;
  title: string;
  summary: string;
  content: string;
  cover_image: string;
  status: string;
  creator: string;
  create_date: string;
  pv: number;
  uv: number;
}

const API_BASE = 'http://localhost:3001/api';

const TABS = [
  { key: 'all', label: '全部', category: '' },
  { key: 'company', label: '公司新闻', category: '公司新闻' },
  { key: 'media', label: '媒体关注', category: '媒体关注' },
  { key: 'party', label: '党建动态', category: '党建动态' },
  { key: 'media-center', label: '多媒体中心', category: '多媒体中心' },
  { key: 'disclosure', label: '信息公开', category: '信息公开' },
];

const News = () => {
  const [activeTab, setActiveTab] = useState('all');
  const [newsList, setNewsList] = useState<NewsItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(6);
  const [total, setTotal] = useState(0);
  const [year, setYear] = useState('');
  const [month, setMonth] = useState('');
  const [keyword, setKeyword] = useState('');
  const [pendingKeyword, setPendingKeyword] = useState('');

  const fetchNews = async (opts: { append?: boolean; pageNum?: number } = {}) => {
    const isAppend = !!opts.append;
    if (isAppend) setLoadingMore(true); else setLoading(true);
    const currentTab = TABS.find(t => t.key === activeTab);
    const currentPage = opts.pageNum || (isAppend ? page + 1 : 1);
    try {
      const res = await axios.get(`${API_BASE}/news`, {
        params: {
          page: currentPage,
          pageSize,
          enabled: 1,
          category: currentTab?.category || undefined,
          year: year || undefined,
          month: month || undefined,
          keyword: keyword || undefined,
        }
      });
      if (res.data.code === 200) {
        const newItems = res.data.data.list as NewsItem[];
        if (isAppend) {
          setNewsList(prev => [...prev, ...newItems]);
        } else {
          setNewsList(newItems);
        }
        setTotal(res.data.data.total);
        setPage(currentPage);
        // 浏览上报：每个 id 当日首次算 UV
        const today = new Date().toDateString();
        newItems.forEach((n: NewsItem) => {
          const uvKey = `news_uv_${n.id}_${today}`;
          const isUnique = !localStorage.getItem(uvKey);
          if (isUnique) localStorage.setItem(uvKey, '1');
          axios.post(`${API_BASE}/news/${n.id}/view`, { isUnique }).catch(() => {});
        });
      }
    } catch (error) {
      console.error('获取新闻列表失败:', error);
    }
    if (isAppend) setLoadingMore(false); else setLoading(false);
  };

  useEffect(() => {
    fetchNews({ append: false, pageNum: 1 });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, year, month, keyword]);

  const handleSearch = () => {
    setKeyword(pendingKeyword.trim());
  };

  const handleReset = () => {
    setYear('');
    setMonth('');
    setPendingKeyword('');
    setKeyword('');
  };

  const handleLoadMore = () => {
    fetchNews({ append: true });
  };

  const hasMore = newsList.length < total;

  const formatDate = (dateStr: string) => {
    if (!dateStr) return { day: '', month: '' };
    const d = new Date(dateStr.replace(' ', 'T'));
    return {
      day: String(d.getDate()).padStart(2, '0'),
      month: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    };
  };

  const generateBanner = (tab: string) => {
    const prompts: Record<string, string> = {
      company: 'Cinematic%20wide%20banner%20of%20modern%20global%20travel%20agency%20headquarters%2C%20aerial%20view%20of%20world%20map%20with%20glowing%20routes%2C%20luxury%20business%20atmosphere%2C%20deep%20red%20and%20dark%20blue%20tones%2C%20premium%20corporate%20photography',
      media: 'Press%20conference%20scene%20with%20cameras%20and%20microphones%2C%20media%20coverage%20of%20travel%20industry%20event%2C%20dramatic%20lighting%2C%20professional%20photojournalism%20style',
      party: 'Chinese%20Communist%20Party%20flag%20with%20modern%20architecture%20background%2C%20red%20and%20gold%20color%20scheme%2C%20formal%20and%20dignified%20atmosphere',
      'media-center': 'Multimedia%20studio%20with%20screens%20and%20video%20production%20equipment%2C%20modern%20broadcasting%20facility%2C%20dynamic%20lighting',
      disclosure: 'Transparent%20glass%20building%20symbolizing%20information%20disclosure%2C%20sunlight%20rays%2C%20clean%20and%20professional%20architecture',
    };
    return `https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=${prompts[tab] || prompts.company}&image_size=landscape_16_9`;
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <TopNav />
      <MainMenu />

      {/* 大气Banner */}
      <div className="relative h-[420px] overflow-hidden">
        <img
          src={generateBanner(activeTab)}
          alt="众信动态"
          className="absolute inset-0 w-full h-full object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/50 to-transparent" />
        <div className="relative max-w-[1200px] mx-auto px-4 h-full flex flex-col justify-center">
          <h1 className="text-5xl font-bold text-white mb-4 tracking-wide">
            {TABS.find(t => t.key === activeTab)?.label || '众信动态'}
          </h1>
          <p className="text-lg text-white/80 max-w-2xl">
            {activeTab === 'all' && '聚焦众信旅游最新动态，见证品牌每一刻成长'}
            {activeTab === 'company' && '了解众信旅游最新动态，与众信一起看世界'}
            {activeTab === 'media' && '聚焦行业前沿，见证众信旅游的品牌力量'}
            {activeTab === 'party' && '党建引领发展，凝聚奋进力量'}
            {activeTab === 'media-center' && '视频影像记录，传递众信声音'}
            {activeTab === 'disclosure' && '公开透明运作，接受社会监督'}
          </p>
          <nav className="absolute bottom-0 left-0 right-0 max-w-[1200px] mx-auto px-4 flex items-center gap-8 overflow-x-auto">
            {TABS.map(tab => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`pb-4 text-base font-medium transition-colors relative ${
                  activeTab === tab.key
                    ? 'text-white'
                    : 'text-white/60 hover:text-white/90'
                }`}
              >
                {tab.label}
                {activeTab === tab.key && (
                  <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-red-500" />
                )}
              </button>
            ))}
          </nav>
        </div>
      </div>

      <div className="max-w-[1200px] mx-auto px-4 py-8">
        {/* 筛选区 */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6 flex items-center gap-3">
          <select
            value={year}
            onChange={(e) => setYear(e.target.value)}
            className="flex-1 px-4 py-2.5 border border-gray-200 rounded text-sm text-gray-700 focus:outline-none focus:border-red-400"
          >
            <option value="">新闻发布年份</option>
            <option value="2026">2026</option>
            <option value="2025">2025</option>
            <option value="2024">2024</option>
          </select>
          <select
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            className="flex-1 px-4 py-2.5 border border-gray-200 rounded text-sm text-gray-700 focus:outline-none focus:border-red-400"
          >
            <option value="">新闻发布月份</option>
            {Array.from({ length: 12 }, (_, i) => (
              <option key={i + 1} value={i + 1}>{i + 1}月</option>
            ))}
          </select>
          <div className="flex-[2] relative">
            <input
              type="text"
              value={pendingKeyword}
              onChange={(e) => setPendingKeyword(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSearch(); }}
              placeholder="输入关键词（按回车搜索）"
              className="w-full px-4 py-2.5 pr-10 border border-gray-200 rounded text-sm focus:outline-none focus:border-red-400"
            />
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          </div>
          <button
            onClick={handleSearch}
            className="px-5 py-2.5 bg-red-500 text-white text-sm rounded hover:bg-red-600 transition-colors"
          >
            搜索
          </button>
          <button
            onClick={handleReset}
            title="重置"
            className="w-11 h-11 flex items-center justify-center bg-gray-800 text-white rounded hover:bg-gray-700 transition-colors"
          >
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>

        {/* 新闻列表 - 时间轴双栏布局 */}
        <div className="space-y-5">
          {loading ? (
            <div className="bg-white rounded-lg p-12 text-center text-gray-500">加载中...</div>
          ) : newsList.length === 0 ? (
            <div className="bg-white rounded-lg p-12 text-center text-gray-500">暂无新闻</div>
          ) : (
            newsList.map((news) => {
              const { day, month: m } = formatDate(news.create_date);
              return (
                <Link
                  key={news.id}
                  to={`/news/${news.id}`}
                  className="bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow overflow-hidden flex cursor-pointer"
                >
                  {/* 左侧红色日期块 */}
                  <div className="w-32 bg-gradient-to-br from-red-500 to-red-600 flex flex-col items-center justify-center text-white flex-shrink-0">
                    <div className="text-4xl font-bold">{day}</div>
                    <div className="text-sm mt-1 text-white/90">{m}</div>
                  </div>
                  {/* 中间标题区域 */}
                  <div className="flex-1 p-6 border-l border-gray-100">
                    <h3 className="text-xl font-bold text-gray-900 hover:text-red-600 transition-colors mb-3">
                      {news.title}
                    </h3>
                    <div className="flex items-center gap-4 text-xs text-gray-500 mb-3">
                      <span className="flex items-center gap-1">
                        <Eye className="w-3.5 h-3.5" />
                        {(news.pv || 0).toLocaleString()}次
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 line-clamp-2 leading-relaxed">
                      {(news.content?.replace(/<[^>]*>/g, '') || news.summary || '点击查看详情...').substring(0, 120)}
                    </p>
                  </div>
                  {/* 右侧封面图 */}
                  <div className="w-72 flex-shrink-0 p-5">
                    <div className="w-full h-40 bg-gradient-to-br from-gray-100 to-gray-200 rounded overflow-hidden">
                      {news.cover_image ? (
                        <img src={news.cover_image} alt={news.title} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-gray-400 text-sm">
                          新闻封面
                        </div>
                      )}
                    </div>
                  </div>
                </Link>
              );
            })
          )}
        </div>

        {/* 分页/加载更多 */}
        {newsList.length > 0 && (
          <div className="mt-8 text-center">
            {hasMore ? (
              <button
                onClick={handleLoadMore}
                disabled={loadingMore}
                className="inline-flex items-center gap-1 px-6 py-2 text-sm text-gray-600 hover:text-red-500 border border-gray-200 rounded-full hover:border-red-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loadingMore ? '加载中...' : '查看更多'}
                {!loadingMore && <ChevronRight className="w-4 h-4" />}
              </button>
            ) : (
              <div className="text-xs text-gray-400">— 已加载全部 {total} 条 —</div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default News;